}

"use client";

import { useState, useTransition, useId } from "react";
import type { Category } from "@/lib/types";
import { parseAdminProductCsv, type AdminCsvProduct } from "@/lib/admin-csv";
import { bulkImportProductsAction } from "@/app/admin/actions";
import {
  FileSpreadsheet,
  UploadCloud,
  CheckCircle2,
  AlertTriangle,
  Download,
  X,
  FileText,
  Table,
  ExternalLink,
  Layers,
  Sparkles,
} from "lucide-react";

interface BulkImportModalProps {
  categories: Category[];
  isOpen: boolean;
  onClose: () => void;
  onSuccess: (count: number) => void;
}

export function BulkImportModal({
  categories,
  isOpen,
  onClose,
  onSuccess,
}: BulkImportModalProps) {
  const [mode, setMode] = useState<"file" | "paste">("file");
  const [csvText, setCsvText] = useState("");
  const [fileName, setFileName] = useState<string | null>(null);
  const [parsedProducts, setParsedProducts] = useState<AdminCsvProduct[]>([]);
  const [parseError, setParseError] = useState<string | null>(null);
  const [isPending, startTransition] = useTransition();
  const fileInputId = useId();

  if (!isOpen) return null;

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setFileName(file.name);
    setParseError(null);

    const reader = new FileReader();
    reader.onload = (event) => {
      const content = String(event.target?.result ?? "");
      setCsvText(content);
      parseContent(content);
    };
    reader.onerror = () => {
      setParseError("No se pudo leer el archivo seleccionado.");
    };
    reader.readAsText(file, "UTF-8");
  };

  const handlePasteChange = (text: string) => {
    setCsvText(text);
    setParseError(null);
    if (text.trim()) {
      parseContent(text);
    } else {
      setParsedProducts([]);
    }
  };

  const parseContent = (text: string) => {
    try {
      const validCategories = new Set(categories.flatMap((category) => [category.name.toLowerCase().trim(), category.slug.toLowerCase().trim()]));
      const items = parseAdminProductCsv(text, validCategories);
      setParsedProducts(items);
      setParseError(null);
    } catch (err: unknown) {
      setParsedProducts([]);
      setParseError(err instanceof Error ? err.message : "Error al procesar el CSV.");
    }
  };

  const handleDownloadTemplate = () => {
    const mainCats = categories.filter((c) => !c.parentId);
    const cat1 = mainCats[0]?.name || "Herramientas";
    const cat2 = mainCats[1]?.name || mainCats[0]?.name || "Cosméticos";

    const csvTemplate = `Titulo,Categoría,PrecioMinorista,PrecioMayorista,MinMayorista,SKU,Marca,Modelo,EnlaceProveedor,CostoProveedor,Descripción
"Taladro Percutor 20V Industrial",${cat1},89900,69900,2,TOTAL-TDLI2001,Total Tools,TDLI2001,https://totalherramientasoficial.com.py/item/1,45000,"Taladro inalámbrico con batería de litio y cargador rápido"
"Serum Facial Hidratante 50ml",${cat2},34900,26500,3,SKIN-CENT-50,Skin1004,Centella,https://atacadousa.com.py/item/2,18000,"Tratamiento intensivo con extracto puro de centella asiática"`;

    const blob = new Blob([csvTemplate], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "plantilla-productos-mya.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (parsedProducts.length === 0) return;

    startTransition(async () => {
      try {
        const res = await bulkImportProductsAction(parsedProducts);
        onSuccess(res.importedCount);
        onClose();
      } catch (err: unknown) {
        setParseError(err instanceof Error ? err.message : "Error al importar productos.");
      }
    });
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-2 sm:p-4 backdrop-blur-xs animate-in fade-in">
      <div className="relative w-full max-w-4xl min-h-0 flex flex-col rounded-2xl bg-white border border-zinc-200 shadow-2xl overflow-hidden max-h-[calc(100dvh-1rem)] sm:max-h-[92dvh]">
        {/* Header */}
        <div className="flex items-center justify-between border-b border-zinc-200 p-5 bg-white shrink-0">
          <div className="flex items-center gap-2.5">
            <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-sky-100 text-sky-700">
              <FileSpreadsheet className="h-5 w-5" />
            </div>
            <div>
              <h3 className="text-lg font-bold text-zinc-950">Importación Masiva de Productos</h3>
              <p className="text-xs text-zinc-500">Cargá tu catálogo completo en formato CSV.</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="rounded-full p-2 text-zinc-400 hover:bg-zinc-100 hover:text-zinc-600 transition cursor-pointer"
            type="button"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="min-h-0 flex flex-col flex-1 overflow-hidden">
          <div className="min-h-0 p-4 sm:p-6 space-y-5 overflow-y-auto overscroll-contain flex-1">
            {/* Top Bar with Template & Mode switcher */}
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 bg-zinc-50 p-3.5 rounded-2xl border border-zinc-200">
              <div className="inline-flex rounded-xl bg-zinc-200/80 p-1">
                <button
                  type="button"
                  onClick={() => setMode("file")}
                  className={`inline-flex items-center gap-1.5 rounded-lg px-3.5 py-1.5 text-xs font-bold transition-all cursor-pointer ${
                    mode === "file" ? "bg-white text-zinc-950 shadow-xs" : "text-zinc-600 hover:text-zinc-950"
                  }`}
                >
                  <UploadCloud className="h-3.5 w-3.5" /> Subir Archivo .CSV
                </button>
                <button
                  type="button"
                  onClick={() => setMode("paste")}
                  className={`inline-flex items-center gap-1.5 rounded-lg px-3.5 py-1.5 text-xs font-bold transition-all cursor-pointer ${
                    mode === "paste" ? "bg-white text-zinc-950 shadow-xs" : "text-zinc-600 hover:text-zinc-950"
                  }`}
                >
                  <FileText className="h-3.5 w-3.5" /> Pegar Texto CSV
                </button>
              </div>

              <button
                type="button"
                onClick={handleDownloadTemplate}
                className="inline-flex items-center gap-1.5 rounded-xl border border-sky-300 bg-sky-50 px-3.5 py-1.5 text-xs font-bold text-sky-800 hover:bg-sky-100 transition-colors cursor-pointer"
              >
                <Download className="h-3.5 w-3.5 text-sky-600" />
                Descargar Plantilla CSV Oficial
              </button>
            </div>

            {/* Input area */}
            {mode === "file" ? (
              <div>
                <label
                  htmlFor={fileInputId}
                  className="flex flex-col items-center justify-center rounded-2xl border-2 border-dashed border-zinc-300 bg-zinc-50/50 p-8 text-center hover:bg-zinc-100/50 hover:border-sky-500 transition-colors cursor-pointer"
                >
                  <UploadCloud className="h-10 w-10 text-sky-600 mb-2" />
                  <p className="text-sm font-bold text-zinc-800">
                    {fileName ? fileName : "Arrastrá tu archivo .CSV o hacé click para seleccionarlo"}
                  </p>
                  <p className="text-xs text-zinc-400 mt-1">Formato admitido: CSV o TXT delimitado por comas</p>
                  <input
                    id={fileInputId}
                    type="file"
                    accept=".csv,text/csv,text/plain"
                    onChange={handleFileChange}
                    className="hidden"
                  />
                </label>
              </div>
            ) : (
              <div className="space-y-2">
                <div className="flex justify-between items-center text-xs font-bold text-zinc-700">
                  <span>Pegar filas CSV:</span>
                  <button
                    type="button"
                    onClick={() => {
                      const mainCats = categories.filter((c) => !c.parentId);
                      const cat1 = mainCats[0]?.name || "Herramientas";
                      const sample = `Titulo,Categoría,PrecioMinorista,PrecioMayorista,MinMayorista,SKU,Marca,Modelo,EnlaceProveedor,CostoProveedor,Descripción\n"Taladro Percutor 20V",${cat1},89900,69900,2,TOTAL-001,Total Tools,TDLI2001,https://totalherramientasoficial.com.py/home,45000,"Taladro profesional con maletín"`;
                      handlePasteChange(sample);
                    }}
                    className="text-sky-600 hover:underline cursor-pointer"
                  >
                    Insertar ejemplo
                  </button>
                </div>
                <textarea
                  rows={6}
                  value={csvText}
                  onChange={(e) => handlePasteChange(e.target.value)}
                  placeholder="Titulo, Categoría, PrecioMinorista, PrecioMayorista, MinMayorista, SKU, Marca, Modelo, EnlaceProveedor, CostoProveedor, Descripción..."
                  className="w-full rounded-xl border border-zinc-300 p-3 font-mono text-xs focus:border-sky-600 focus:bg-white bg-zinc-50 focus:outline-hidden"
                />
              </div>
            )}

            {/* Error Banner */}
            {parseError && (
              <div className="rounded-xl border border-rose-300 bg-rose-50 p-4 text-xs font-semibold text-rose-800 flex items-start gap-2">
                <AlertTriangle className="h-4 w-4 text-rose-600 shrink-0 mt-0.5" />
                <span>{parseError}</span>
              </div>
            )}

            {/* Live Preview Table */}
            {parsedProducts.length > 0 && (
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-xs font-bold text-zinc-800 uppercase tracking-wider flex items-center gap-1.5">
                    <Table className="h-3.5 w-3.5 text-emerald-600" />
                    Vista Previa ({parsedProducts.length} productos listos para importar)
                  </span>
                  <span className="rounded-full bg-emerald-50 px-2.5 py-0.5 text-[11px] font-bold text-emerald-700 border border-emerald-200">
                    ✓ Todos los datos validados
                  </span>
                </div>

                <div className="overflow-auto rounded-xl border border-zinc-200 max-h-56 scrollbar-thin">
                  <table className="w-full min-w-[620px] text-left text-xs">
                    <thead className="bg-zinc-100 text-zinc-600 font-bold sticky top-0 border-b border-zinc-200">
                      <tr>
                        <th className="p-2.5">Título</th>
                        <th className="p-2.5">Categoría</th>
                        <th className="p-2.5">PVP</th>
                        <th className="p-2.5">Mayorista</th>
                        <th className="p-2.5">SKU / Marca</th>
                        <th className="p-2.5">Enlace Proveedor</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-zinc-200">
                      {parsedProducts.slice(0, 15).map((p, idx) => (
                        <tr key={idx} className="hover:bg-zinc-50">
                          <td className="p-2.5 font-semibold text-zinc-900 line-clamp-1 max-w-[200px]">
                            {p.title}
                          </td>
                          <td className="p-2.5 text-zinc-600">{p.categoryName}</td>
                          <td className="p-2.5 font-bold text-zinc-900">${p.retailPrice.toLocaleString("es-AR")}</td>
                          <td className="p-2.5 text-zinc-600">
                            ${p.wholesalePrice.toLocaleString("es-AR")} ({p.wholesaleMinQuantity}+)
                          </td>
                          <td className="p-2.5 text-zinc-500 font-mono text-[11px]">
                            {p.sku || p.brand || "—"}
                          </td>
                          <td className="p-2.5 text-zinc-500 max-w-[150px] truncate">
                            {p.sourceUrl ? (
                              <span className="text-sky-600 font-semibold truncate block">
                                {p.sourceUrl}
                              </span>
                            ) : (
                              <span className="text-zinc-400 italic">Sin enlace</span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                {parsedProducts.length > 15 && (
                  <p className="text-[11px] text-zinc-500 text-right">
                    ... y {parsedProducts.length - 15} productos más incluidos en la importación.
                  </p>
                )}
              </div>
            )}
          </div>

          {/* Footer */}
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 p-4 sm:p-5 bg-zinc-50 border-t border-zinc-200 shrink-0">
            <span className="text-xs text-zinc-500 text-center sm:text-left">
              {parsedProducts.length > 0 ? `${parsedProducts.length} productos detectados` : "Esperando archivo..."}
            </span>
            <div className="flex items-center gap-2.5 w-full sm:w-auto justify-end">
              <button
                type="button"
                onClick={onClose}
                className="flex-1 sm:flex-initial px-4 py-2.5 text-xs font-semibold text-zinc-700 hover:bg-zinc-200 rounded-xl cursor-pointer transition-colors text-center"
              >
                Cancelar
              </button>
              <button
                type="submit"
                disabled={isPending || parsedProducts.length === 0}
                className="flex-1 sm:flex-initial inline-flex items-center justify-center gap-2 px-6 py-2.5 text-xs font-bold text-white bg-sky-600 hover:bg-sky-700 rounded-xl shadow-md transition cursor-pointer disabled:opacity-50 text-center"
              >
                {isPending ? (
                  "Importando productos…"
                ) : (
                  <>
                    <CheckCircle2 className="h-4 w-4 shrink-0" />
                    Importar {parsedProducts.length} Productos
                  </>
                )}
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import { useState, useTransition, useId } from "react";
import { optimizeProductPhoto } from "@/lib/image-upload";
import type { Category } from "@/lib/types";
import { createCategoryAction, updateCategoryAction } from "@/app/admin/actions";
import {
  FolderPlus,
  FolderOpen,
  Edit,
  X,
  Upload,
  CheckCircle2,
  AlertTriangle,
  Layers,
  Sparkles,
  ExternalLink,
} from "lucide-react";

interface CategoryModalProps {
  isOpen: boolean;
  categories: Category[];
  initialParentId?: string;
  categoryToEdit?: Category | null;
  onClose: () => void;
  onSuccess: (message: string) => void;
}

export function CategoryModal({
  isOpen,
  categories,
  initialParentId = "",
  categoryToEdit,
  onClose,
  onSuccess,
}: CategoryModalProps) {
  const isEditing = Boolean(categoryToEdit);
  const [name, setName] = useState(categoryToEdit?.name || "");
  const [parentId, setParentId] = useState(
    categoryToEdit ? categoryToEdit.parentId || "" : initialParentId
  );
  const [description, setDescription] = useState(categoryToEdit?.description || "");
  const [displayOrder, setDisplayOrder] = useState<number>(categoryToEdit?.displayOrder ?? 0);
  const [wholesaleOnly, setWholesaleOnly] = useState(Boolean(categoryToEdit?.wholesaleOnly));
  const [customImageUrl, setCustomImageUrl] = useState(categoryToEdit?.imageUrl || "");
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(categoryToEdit?.imageUrl || null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isPending, startTransition] = useTransition();
  const fileInputId = useId();

  if (!isOpen) return null;

  // Potential parents (only top-level categories, excluding itself if editing)
  const availableParents = categories.filter(
    (c) => !c.parentId && (!categoryToEdit || c.id !== categoryToEdit.id)
  );

  const slugPreview = name
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const input = e.target.files?.[0];
    if (input) {
      try {
      const file = await optimizeProductPhoto(input);
      setImageFile(file);
      setCustomImageUrl("");
      const reader = new FileReader();
      reader.onload = (event) => {
        setImagePreview(String(event.target?.result ?? ""));
      };
      reader.readAsDataURL(file);
      } catch (err) { setErrorMsg(err instanceof Error ? err.message : "No se pudo preparar la foto."); }
    }
  };

  const handleUrlChange = (url: string) => {
    setCustomImageUrl(url);
    setImageFile(null);
    setImagePreview(url.trim() ? url : null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) {
      setErrorMsg("El nombre de la categoría es obligatorio.");
      return;
    }

    const formData = new FormData();
    if (isEditing && categoryToEdit) {
      formData.set("id", categoryToEdit.id);
    }
    formData.set("name", name.trim());
    formData.set("parent_id", parentId);
    formData.set("description", description.trim());
    formData.set("display_order", String(displayOrder));
    if (wholesaleOnly) formData.set("is_wholesale_only", "on");
    if (isEditing && categoryToEdit) formData.set("existing_image_url", categoryToEdit.imageUrl || "");

    if (imageFile) {
      formData.set("image", imageFile);
    } else if (customImageUrl.trim()) {
      formData.set("custom_image_url", customImageUrl.trim());
    }

    startTransition(async () => {
      try {
        if (isEditing) {
          await updateCategoryAction(formData);
          onSuccess(`Categoría "${name}" actualizada con éxito.`);
        } else {
          await createCategoryAction(formData);
          onSuccess(`Categoría "${name}" creada con éxito.`);
        }
        onClose();
      } catch (err: unknown) {
        setErrorMsg(err instanceof Error ? err.message : "Error al guardar la categoría.");
      }
    });
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center overflow-y-auto bg-black/60 p-2 sm:p-4 backdrop-blur-xs animate-in fade-in">
      <div className="relative my-auto w-full max-w-lg min-h-0 flex flex-col rounded-2xl bg-white border border-zinc-200 shadow-2xl overflow-hidden max-h-[calc(100dvh-1rem)] sm:max-h-[92dvh]">
        {/* Header */}
        <div className="flex items-center justify-between border-b border-zinc-200 p-4 sm:p-5 bg-white shrink-0">
          <div className="flex items-center gap-2.5">
            <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-emerald-100 text-emerald-700 shrink-0">
              {isEditing ? <Edit className="h-5 w-5" /> : <FolderPlus className="h-5 w-5" />}
            </div>
            <div className="min-w-0">
              <h3 className="text-base sm:text-lg font-bold text-zinc-950 truncate">
                {isEditing ? "Editar Categoría" : "Nueva Categoría"}
              </h3>
              <p className="text-[11px] sm:text-xs text-zinc-500 truncate">
                {isEditing ? "Modificá los datos del rubro." : "Creá un rubro o subcategoría para tu catálogo."}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="rounded-full p-2 text-zinc-400 hover:bg-zinc-100 hover:text-zinc-600 transition cursor-pointer shrink-0"
            type="button"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="min-h-0 flex-1 flex flex-col overflow-hidden">
          <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain p-4 sm:p-6 space-y-4">
          {/* Name & Slug preview */}
          <div>
            <label className="block text-xs font-bold uppercase tracking-wider text-zinc-700">
              Nombre de la Categoría *
            </label>
            <input
              type="text"
              required
              placeholder="Ej: Herramientas Eléctricas, Cosméticos..."
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-sm font-semibold text-zinc-900 focus:border-emerald-500 focus:outline-hidden focus:ring-2 focus:ring-emerald-500/20"
            />
            {slugPreview && (
              <span className="block mt-1 text-[11px] text-zinc-400 font-mono">
                Enlace en tienda: /catalogo?category={slugPreview}
              </span>
            )}
          </div>

          {/* Hierarchy: Parent Category */}
          <div>
            <label className="block text-xs font-bold uppercase tracking-wider text-zinc-700">
              Jerarquía / Categoría Padre
            </label>
            <select
              value={parentId}
              onChange={(e) => setParentId(e.target.value)}
              className="mt-1 w-full rounded-xl border border-zinc-300 bg-white p-2.5 text-sm font-medium text-zinc-800 focus:border-emerald-500 focus:outline-hidden"
            >
              <option value="">-- Ninguna (Categoría Principal) --</option>
              {availableParents.map((parent) => (
                <option key={parent.id} value={parent.id}>
                  📁 Subcategoría de: {parent.name}
                </option>
              ))}
            </select>
            <span className="block mt-1 text-[11px] text-zinc-500">
              Dejá en blanco si es un rubro principal, o elegí un rubro para crear una subcategoría.
            </span>
          </div>

          {/* Description */}
          <div>
            <label className="block text-xs font-bold uppercase tracking-wider text-zinc-700">
              Descripción (Opcional)
            </label>
            <textarea
              rows={2}
              placeholder="Breve descripción que se mostrará en el catálogo..."
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-xs text-zinc-800 focus:border-emerald-500 focus:outline-hidden"
            />
          </div>

          {/* Image Upload & Preview */}
          <div className="space-y-2">
            <label className="block text-xs font-bold uppercase tracking-wider text-zinc-700">
              Imagen de Portada
            </label>
            <div className="flex items-start gap-4">
              {/* Preview */}
              <div className="relative h-20 w-24 shrink-0 overflow-hidden rounded-xl border border-zinc-200 bg-zinc-100 flex items-center justify-center">
                {imagePreview ? (
                  <img
                    src={imagePreview}
                    alt="Vista previa"
                    className="h-full w-full object-cover"
                    onError={() => setImagePreview(null)}
                  />
                ) : (
                  <FolderOpen className="h-7 w-7 text-zinc-400" />
                )}
              </div>

              {/* Upload controls */}
              <div className="flex-1 space-y-2">
                <label
                  htmlFor={fileInputId}
                  className="inline-flex items-center gap-1.5 rounded-xl border border-zinc-300 bg-white px-3 py-1.5 text-xs font-semibold text-zinc-700 hover:bg-zinc-50 cursor-pointer shadow-2xs"
                >
                  <Upload className="h-3.5 w-3.5" /> Subir archivo de imagen
                  <input
                    id={fileInputId}
                    type="file"
                    accept="image/jpeg,image/png,image/webp"
                    onChange={handleFileChange}
                    className="hidden"
                  />
                </label>
                <input
                  type="url"
                  placeholder="O ingresá URL externa (https://...)"
                  value={customImageUrl}
                  onChange={(e) => handleUrlChange(e.target.value)}
                  className="w-full rounded-xl border border-zinc-300 p-2 text-xs text-zinc-700 focus:border-emerald-500"
                />
              </div>
            </div>
          </div>

          {/* Options: Priority & Wholesale */}
          <div className="grid grid-cols-2 gap-3 pt-1">
            <div>
              <label className="block text-xs font-semibold text-zinc-700">
                Orden de Visualización
              </label>
              <input
                type="number"
                min="0"
                step="1"
                value={displayOrder}
                onChange={(e) => setDisplayOrder(parseInt(e.target.value, 10) || 0)}
                className="mt-1 w-full rounded-xl border border-zinc-300 p-2 text-xs font-bold"
              />
            </div>

            <div className="flex items-center pt-5">
              <label className="flex items-center gap-2 text-xs font-semibold text-zinc-800 cursor-pointer">
                <input
                  type="checkbox"
                  checked={wholesaleOnly}
                  onChange={(e) => setWholesaleOnly(e.target.checked)}
                  className="rounded border-zinc-300 text-amber-600 focus:ring-amber-500"
                />
                Exclusiva Mayorista
              </label>
            </div>
          </div>

          {errorMsg && (
            <div className="rounded-xl border border-rose-300 bg-rose-50 p-3 text-xs font-semibold text-rose-800 flex items-start gap-1.5">
              <AlertTriangle className="h-4 w-4 text-rose-600 shrink-0 mt-0.5" />
              <span>{errorMsg}</span>
            </div>
          )}

          </div>

          {/* Sticky Footer */}
          <div className="flex items-center justify-end gap-2.5 p-4 sm:p-5 border-t border-zinc-100 bg-zinc-50 shrink-0">
            <button
              type="button"
              onClick={onClose}
              className="rounded-xl border border-zinc-300 px-4 py-2.5 text-xs font-semibold text-zinc-700 hover:bg-zinc-200 cursor-pointer transition-colors"
            >
              Cancelar
            </button>
            <button
              type="submit"
              disabled={isPending}
              className="inline-flex items-center gap-1.5 rounded-xl bg-emerald-600 hover:bg-emerald-700 px-5 py-2.5 text-xs font-bold text-white shadow-xs disabled:opacity-50 cursor-pointer transition-colors"
            >
              {isPending ? (
                "Guardando…"
              ) : (
                <>
                  <CheckCircle2 className="h-4 w-4" />
                  {isEditing ? "Guardar Cambios" : "Crear Categoría"}
                </>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import {
  Megaphone,
  Share2,
  CheckCircle2,
  AlertCircle,
  Copy,
  Check,
  ExternalLink,
  Sparkles,
  Radio,
  Play,
  Layers,
  ShoppingBag,
  ShieldCheck,
  TrendingUp,
} from "lucide-react";
import {
  getMarketingConfig,
  saveMarketingConfig,
  trackAdsEvent,
  type MarketingConfig,
} from "@/lib/analytics";
import { siteConfig } from "@/lib/site";

export function MarketingHub() {
  const [config, setConfig] = useState<MarketingConfig>(getMarketingConfig());
  const [savedSuccess, setSavedSuccess] = useState(false);
  const [copiedMetaFeed, setCopiedMetaFeed] = useState(false);
  const [copiedGoogleFeed, setCopiedGoogleFeed] = useState(false);
  const [testEventFeedback, setTestEventFeedback] = useState<string | null>(null);

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    saveMarketingConfig(config);
    setSavedSuccess(true);
    setTimeout(() => setSavedSuccess(false), 3000);
  };

  const baseUrl = typeof window !== "undefined" ? window.location.origin : siteConfig.appUrl;
  const metaFeedUrl = `${baseUrl}/api/catalog/meta-feed`;
  const googleFeedUrl = `${baseUrl}/api/catalog/google-feed`;

  const copyToClipboard = async (text: string, type: "meta" | "google") => {
    try {
      await navigator.clipboard.writeText(text);
      if (type === "meta") {
        setCopiedMetaFeed(true);
        setTimeout(() => setCopiedMetaFeed(false), 3000);
      } else {
        setCopiedGoogleFeed(true);
        setTimeout(() => setCopiedGoogleFeed(false), 3000);
      }
    } catch {}
  };

  const handleTestEvent = (eventName: "ViewContent" | "AddToCart" | "InitiateCheckout" | "Purchase") => {
    trackAdsEvent(eventName, {
      content_name: "Producto de Prueba MYA",
      content_ids: ["test-prod-123"],
      value: 150000,
      currency: "ARS",
      quantity: 1,
      transaction_id: `TEST-${Date.now().toString().slice(-6)}`,
      items: [{ id: "test-prod-123", title: "Producto de Prueba MYA", price: 150000, quantity: 1 }],
    });

    setTestEventFeedback(`¡Evento "${eventName}" disparado a los píxeles activos! Revisá la consola (F12) para ver los detalles.`);
    setTimeout(() => setTestEventFeedback(null), 5000);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-200">
      {/* Header Banner */}
      <div className="rounded-2xl border border-blue-200 bg-gradient-to-br from-blue-900 via-indigo-950 to-zinc-950 p-6 md:p-8 text-white shadow-xl relative overflow-hidden">
        <div className="absolute right-0 top-0 translate-x-10 -translate-y-10 w-96 h-96 bg-blue-500/10 rounded-full blur-3xl pointer-events-none" />
        <div className="relative z-10">
          <div className="inline-flex items-center gap-2 rounded-full border border-blue-400/30 bg-blue-500/20 px-3.5 py-1 text-xs font-bold text-blue-200">
            <Megaphone className="h-3.5 w-3.5" />
            Marketing & Ads Ecosystem
          </div>
          <h2 className="mt-3 text-2xl md:text-3xl font-black tracking-tight text-white">
            Centro de Conexión de Publicidad, Píxeles & Catálogos
          </h2>
          <p className="mt-2 text-sm text-zinc-300 max-w-3xl leading-relaxed">
            Dejá tu tienda 100% conectada con <strong>Meta Ads (Facebook e Instagram)</strong>, <strong>Google Ads & GA4</strong> y <strong>TikTok Ads</strong>.
            Solo pegá los IDs de tus píxeles abajo para empezar a medir conversiones (Visualizaciones, Carritos y Compras) y sincronizá tus productos con los Feeds XML automáticos.
          </p>
        </div>
      </div>

      {savedSuccess && (
        <div className="rounded-xl border border-emerald-300 bg-emerald-50 p-4 text-sm font-semibold text-emerald-900 flex items-center gap-3">
          <CheckCircle2 className="h-5 w-5 text-emerald-600 shrink-0" />
          ¡Configuración de marketing guardada exitosamente! Los píxeles configurados ya están activos en toda la tienda.
        </div>
      )}

      {testEventFeedback && (
        <div className="rounded-xl border border-blue-300 bg-blue-50 p-4 text-sm font-semibold text-blue-900 flex items-center gap-3">
          <Sparkles className="h-5 w-5 text-blue-600 shrink-0" />
          {testEventFeedback}
        </div>
      )}

      {/* Grid: Pixel Configuration (Left) & Feeds / Testing (Right) */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Left Column: Pixel IDs Form */}
        <div className="lg:col-span-7 space-y-6">
          <form onSubmit={handleSave} className="rounded-2xl border border-zinc-200 bg-white p-6 shadow-sm space-y-6">
            <div className="flex items-center justify-between border-b border-zinc-100 pb-4">
              <h3 className="text-base font-bold text-zinc-900 flex items-center gap-2">
                <Radio className="h-5 w-5 text-blue-600" />
                Píxeles y Cuentas de Anuncios
              </h3>
              <span className="text-xs text-zinc-500 font-medium">Guarda al instante</span>
            </div>

            {/* Meta Pixel */}
            <div className="space-y-1.5 p-4 rounded-xl border border-zinc-200 bg-zinc-50">
              <div className="flex items-center justify-between">
                <label className="text-xs font-bold uppercase tracking-wider text-zinc-800 flex items-center gap-2">
                  <span className="w-2.5 h-2.5 rounded-full bg-blue-600 inline-block" />
                  Meta Pixel ID (Facebook / Instagram Ads)
                </label>
                <span
                  className={`text-[10px] font-extrabold px-2 py-0.5 rounded-full ${
                    config.metaPixelId ? "bg-emerald-100 text-emerald-800" : "bg-zinc-200 text-zinc-600"
                  }`}
                >
                  {config.metaPixelId ? "Activo" : "No configurado"}
                </span>
              </div>
              <input
                type="text"
                placeholder="Ej. 123456789012345"
                value={config.metaPixelId}
                onChange={(e) => setConfig({ ...config, metaPixelId: e.target.value })}
                className="w-full rounded-xl border border-zinc-300 bg-white px-3.5 py-2 text-sm font-medium text-zinc-900 focus:border-blue-500 focus:outline-none font-mono"
              />
              <p className="text-[11px] text-zinc-500">
                Ubicación en Meta: Administrador de Eventos ➔ Administrador de Anuncios ➔ Configuración de Orígenes de Datos.
              </p>
            </div>

            {/* Google Ads */}
            <div className="space-y-1.5 p-4 rounded-xl border border-zinc-200 bg-zinc-50">
              <div className="flex items-center justify-between">
                <label className="text-xs font-bold uppercase tracking-wider text-zinc-800 flex items-center gap-2">
                  <span className="w-2.5 h-2.5 rounded-full bg-amber-500 inline-block" />
                  Google Ads Conversion ID (Tag)
                </label>
                <span
                  className={`text-[10px] font-extrabold px-2 py-0.5 rounded-full ${
                    config.googleAdsId ? "bg-emerald-100 text-emerald-800" : "bg-zinc-200 text-zinc-600"
                  }`}
                >
                  {config.googleAdsId ? "Activo" : "No configurado"}
                </span>
              </div>
              <input
                type="text"
                placeholder="Ej. AW-123456789"
                value={config.googleAdsId}
                onChange={(e) => setConfig({ ...config, googleAdsId: e.target.value })}
                className="w-full rounded-xl border border-zinc-300 bg-white px-3.5 py-2 text-sm font-medium text-zinc-900 focus:border-blue-500 focus:outline-none font-mono"
              />
              <p className="text-[11px] text-zinc-500">
                Ubicación en Google Ads: Herramientas ➔ Medición ➔ Conversiones ➔ Google Tag (AW-XXXXXXXX).
              </p>
            </div>

            {/* Google Analytics 4 */}
            <div className="space-y-1.5 p-4 rounded-xl border border-zinc-200 bg-zinc-50">
              <div className="flex items-center justify-between">
                <label className="text-xs font-bold uppercase tracking-wider text-zinc-800 flex items-center gap-2">
                  <span className="w-2.5 h-2.5 rounded-full bg-orange-600 inline-block" />
                  Google Analytics 4 (GA4 ID de Medición)
                </label>
                <span
                  className={`text-[10px] font-extrabold px-2 py-0.5 rounded-full ${
                    config.ga4Id ? "bg-emerald-100 text-emerald-800" : "bg-zinc-200 text-zinc-600"
                  }`}
                >
                  {config.ga4Id ? "Activo" : "No configurado"}
                </span>
              </div>
              <input
                type="text"
                placeholder="Ej. G-ABC123XYZ"
                value={config.ga4Id}
                onChange={(e) => setConfig({ ...config, ga4Id: e.target.value })}
                className="w-full rounded-xl border border-zinc-300 bg-white px-3.5 py-2 text-sm font-medium text-zinc-900 focus:border-blue-500 focus:outline-none font-mono"
              />
              <p className="text-[11px] text-zinc-500">
                Ubicación en GA4: Administrar ➔ Flujos de datos ➔ ID de medición (G-XXXXXXXXXX).
              </p>
            </div>

            {/* TikTok Pixel */}
            <div className="space-y-1.5 p-4 rounded-xl border border-zinc-200 bg-zinc-50">
              <div className="flex items-center justify-between">
                <label className="text-xs font-bold uppercase tracking-wider text-zinc-800 flex items-center gap-2">
                  <span className="w-2.5 h-2.5 rounded-full bg-pink-600 inline-block" />
                  TikTok Pixel ID
                </label>
                <span
                  className={`text-[10px] font-extrabold px-2 py-0.5 rounded-full ${
                    config.tiktokPixelId ? "bg-emerald-100 text-emerald-800" : "bg-zinc-200 text-zinc-600"
                  }`}
                >
                  {config.tiktokPixelId ? "Activo" : "No configurado"}
                </span>
              </div>
              <input
                type="text"
                placeholder="Ej. C1234567890123456789"
                value={config.tiktokPixelId}
                onChange={(e) => setConfig({ ...config, tiktokPixelId: e.target.value })}
                className="w-full rounded-xl border border-zinc-300 bg-white px-3.5 py-2 text-sm font-medium text-zinc-900 focus:border-blue-500 focus:outline-none font-mono"
              />
              <p className="text-[11px] text-zinc-500">
                Ubicación en TikTok Ads Manager: Assets ➔ Events ➔ Web Events ➔ Pixel ID.
              </p>
            </div>

            {/* Google Tag Manager */}
            <div className="space-y-1.5 p-4 rounded-xl border border-zinc-200 bg-zinc-50">
              <div className="flex items-center justify-between">
                <label className="text-xs font-bold uppercase tracking-wider text-zinc-800 flex items-center gap-2">
                  <span className="w-2.5 h-2.5 rounded-full bg-blue-500 inline-block" />
                  Google Tag Manager (GTM ID - Opcional)
                </label>
                <span
                  className={`text-[10px] font-extrabold px-2 py-0.5 rounded-full ${
                    config.gtmId ? "bg-emerald-100 text-emerald-800" : "bg-zinc-200 text-zinc-600"
                  }`}
                >
                  {config.gtmId ? "Activo" : "No configurado"}
                </span>
              </div>
              <input
                type="text"
                placeholder="Ej. GTM-XXXXXXX"
                value={config.gtmId}
                onChange={(e) => setConfig({ ...config, gtmId: e.target.value })}
                className="w-full rounded-xl border border-zinc-300 bg-white px-3.5 py-2 text-sm font-medium text-zinc-900 focus:border-blue-500 focus:outline-none font-mono"
              />
            </div>

            {/* Options */}
            <div className="flex items-center justify-between pt-2">
              <label className="flex items-center gap-2 text-xs font-bold text-zinc-700 cursor-pointer">
                <input
                  type="checkbox"
                  checked={config.testMode}
                  onChange={(e) => setConfig({ ...config, testMode: e.target.checked })}
                  className="rounded border-zinc-300 text-blue-600 focus:ring-blue-500 h-4 w-4"
                />
                Modo Pruebas / Consola (muestra logs de eventos en F12)
              </label>

              <button
                type="submit"
                className="inline-flex items-center justify-center gap-2 rounded-xl bg-blue-600 px-6 py-2.5 text-xs font-bold text-white hover:bg-blue-700 transition-colors shadow-sm cursor-pointer"
              >
                <Check className="h-4 w-4" />
                Guardar Configuración
              </button>
            </div>
          </form>
        </div>

        {/* Right Column: Catalog Feeds & Live Testing */}
        <div className="lg:col-span-5 space-y-6">
          {/* Product Feeds */}
          <div className="rounded-2xl border border-zinc-200 bg-white p-6 shadow-sm space-y-5">
            <h3 className="text-base font-bold text-zinc-900 flex items-center gap-2">
              <ShoppingBag className="h-5 w-5 text-blue-600" />
              Feeds de Catálogo XML para Anuncios
            </h3>
            <p className="text-xs text-zinc-600 leading-relaxed">
              Conectá tu catálogo con Meta Commerce y Google Shopping. Los feeds se actualizan en tiempo real con stock, precios mayoristas/minoristas e imágenes en alta calidad.
            </p>

            {/* Meta Catalog Feed */}
            <div className="space-y-2 p-3.5 rounded-xl bg-zinc-50 border border-zinc-200">
              <div className="flex items-center justify-between">
                <span className="text-xs font-extrabold text-blue-900">
                  Meta Catalog Feed (Facebook / IG Shopping)
                </span>
                <a
                  href={metaFeedUrl}
                  target="_blank"
                  rel="noreferrer"
                  className="text-[11px] text-blue-600 hover:underline flex items-center gap-1"
                >
                  Ver XML <ExternalLink className="h-3 w-3" />
                </a>
              </div>
              <div className="flex gap-2">
                <input
                  type="text"
                  readOnly
                  value={metaFeedUrl}
                  className="w-full text-xs font-mono bg-white border border-zinc-200 rounded-lg px-2.5 py-1.5 text-zinc-600 select-all"
                />
                <button
                  type="button"
                  onClick={() => copyToClipboard(metaFeedUrl, "meta")}
                  className="shrink-0 inline-flex items-center gap-1.5 px-3 py-1.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-xs font-bold cursor-pointer"
                >
                  {copiedMetaFeed ? <Check className="h-3.5 w-3.5" /> : <Copy className="h-3.5 w-3.5" />}
                  {copiedMetaFeed ? "Copiado" : "Copiar"}
                </button>
              </div>
              <p className="text-[11px] text-zinc-500">
                Pega este enlace en: Meta Commerce Manager ➔ Catálogo ➔ Orígenes de datos ➔ Subida de datos programada (frecuencia diaria).
              </p>
            </div>

            {/* Google Merchant Center Feed */}
            <div className="space-y-2 p-3.5 rounded-xl bg-zinc-50 border border-zinc-200">
              <div className="flex items-center justify-between">
                <span className="text-xs font-extrabold text-amber-900">
                  Google Merchant Center Feed (Google Shopping)
                </span>
                <a
                  href={googleFeedUrl}
                  target="_blank"
                  rel="noreferrer"
                  className="text-[11px] text-amber-700 hover:underline flex items-center gap-1"
                >
                  Ver XML <ExternalLink className="h-3 w-3" />
                </a>
              </div>
              <div className="flex gap-2">
                <input
                  type="text"
                  readOnly
                  value={googleFeedUrl}
                  className="w-full text-xs font-mono bg-white border border-zinc-200 rounded-lg px-2.5 py-1.5 text-zinc-600 select-all"
                />
                <button
                  type="button"
                  onClick={() => copyToClipboard(googleFeedUrl, "google")}
                  className="shrink-0 inline-flex items-center gap-1.5 px-3 py-1.5 bg-amber-600 hover:bg-amber-700 text-white rounded-lg text-xs font-bold cursor-pointer"
                >
                  {copiedGoogleFeed ? <Check className="h-3.5 w-3.5" /> : <Copy className="h-3.5 w-3.5" />}
                  {copiedGoogleFeed ? "Copiado" : "Copiar"}
                </button>
              </div>
              <p className="text-[11px] text-zinc-500">
                Pega este enlace en: Google Merchant Center ➔ Productos ➔ Feeds ➔ Añadir feed principal ➔ Obtención de URL programada.
              </p>
            </div>
          </div>

          {/* Live Events Tester */}
          <div className="rounded-2xl border border-zinc-200 bg-white p-6 shadow-sm space-y-4">
            <h3 className="text-base font-bold text-zinc-900 flex items-center gap-2">
              <Play className="h-5 w-5 text-emerald-600" />
              Probador en Vivo de Conversiones
            </h3>
            <p className="text-xs text-zinc-600">
              Probá que tus píxeles instalados reciban los eventos simulando una acción de usuario:
            </p>

            <div className="grid grid-cols-2 gap-2">
              <button
                type="button"
                onClick={() => handleTestEvent("ViewContent")}
                className="p-2.5 rounded-xl border border-zinc-200 hover:border-blue-400 bg-zinc-50 hover:bg-blue-50 text-left transition-colors cursor-pointer"
              >
                <span className="text-xs font-bold text-zinc-900 block">Probar ViewContent</span>
                <span className="text-[10px] text-zinc-500">Ver ficha de producto</span>
              </button>

              <button
                type="button"
                onClick={() => handleTestEvent("AddToCart")}
                className="p-2.5 rounded-xl border border-zinc-200 hover:border-emerald-400 bg-zinc-50 hover:bg-emerald-50 text-left transition-colors cursor-pointer"
              >
                <span className="text-xs font-bold text-zinc-900 block">Probar AddToCart</span>
                <span className="text-[10px] text-zinc-500">Agregar al carrito</span>
              </button>

              <button
                type="button"
                onClick={() => handleTestEvent("InitiateCheckout")}
                className="p-2.5 rounded-xl border border-zinc-200 hover:border-amber-400 bg-zinc-50 hover:bg-amber-50 text-left transition-colors cursor-pointer"
              >
                <span className="text-xs font-bold text-zinc-900 block">Probar Checkout</span>
                <span className="text-[10px] text-zinc-500">Iniciar proceso de pago</span>
              </button>

              <button
                type="button"
                onClick={() => handleTestEvent("Purchase")}
                className="p-2.5 rounded-xl border border-zinc-200 hover:border-purple-400 bg-zinc-50 hover:bg-purple-50 text-left transition-colors cursor-pointer"
              >
                <span className="text-xs font-bold text-zinc-900 block">Probar Purchase</span>
                <span className="text-[10px] text-zinc-500">Conversión de compra</span>
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Events Reference Guide Table */}
      <div className="rounded-2xl border border-zinc-200 bg-white p-6 shadow-sm space-y-4">
        <h4 className="text-sm font-bold text-zinc-900 flex items-center gap-2">
          <Layers className="h-4 w-4 text-blue-600" />
          Mapeo Automático de Eventos en MYA Importaciones
        </h4>

        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead>
              <tr className="border-b border-zinc-200 text-zinc-500 uppercase tracking-wider">
                <th className="py-2.5 font-bold">Momento / Acción del Cliente</th>
                <th className="py-2.5 font-bold">Meta Pixel (FB/IG)</th>
                <th className="py-2.5 font-bold">Google Ads / GA4</th>
                <th className="py-2.5 font-bold">TikTok Pixel</th>
                <th className="py-2.5 font-bold">Parámetros Enviados</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-zinc-100 font-medium">
              <tr className="hover:bg-zinc-50">
                <td className="py-2.5 font-bold text-zinc-900">Navegación / Entrada a página</td>
                <td className="py-2.5 font-mono text-blue-600">PageView</td>
                <td className="py-2.5 font-mono text-orange-600">page_view</td>
                <td className="py-2.5 font-mono text-pink-600">Page</td>
                <td className="py-2.5 text-zinc-500">Ruta URL, query params</td>
              </tr>
              <tr className="hover:bg-zinc-50">
                <td className="py-2.5 font-bold text-zinc-900">Ver Ficha de Producto o Modal</td>
                <td className="py-2.5 font-mono text-blue-600">ViewContent</td>
                <td className="py-2.5 font-mono text-orange-600">view_item</td>
                <td className="py-2.5 font-mono text-pink-600">ViewContent</td>
                <td className="py-2.5 text-zinc-500">ID, Nombre, Precio, ARS</td>
              </tr>
              <tr className="hover:bg-zinc-50">
                <td className="py-2.5 font-bold text-zinc-900">Agregar al Carrito de Compras</td>
                <td className="py-2.5 font-mono text-blue-600">AddToCart</td>
                <td className="py-2.5 font-mono text-orange-600">add_to_cart</td>
                <td className="py-2.5 font-mono text-pink-600">AddToCart</td>
                <td className="py-2.5 text-zinc-500">ID, Cantidad, Precio total, ARS</td>
              </tr>
              <tr className="hover:bg-zinc-50">
                <td className="py-2.5 font-bold text-zinc-900">Abrir Pantalla de Checkout</td>
                <td className="py-2.5 font-mono text-blue-600">InitiateCheckout</td>
                <td className="py-2.5 font-mono text-orange-600">begin_checkout</td>
                <td className="py-2.5 font-mono text-pink-600">InitiateCheckout</td>
                <td className="py-2.5 text-zinc-500">Valor de orden, N° productos</td>
              </tr>
              <tr className="hover:bg-zinc-50">
                <td className="py-2.5 font-bold text-zinc-900">Confirmación de Pedido / Compra</td>
                <td className="py-2.5 font-mono text-blue-600">Purchase</td>
                <td className="py-2.5 font-mono text-orange-600">purchase + conversion</td>
                <td className="py-2.5 font-mono text-pink-600">CompletePayment</td>
                <td className="py-2.5 text-zinc-500">Código de orden, Monto total ARS, Ítems</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useMemo, useTransition } from "react";
import {
  Percent,
  TrendingUp,
  Calculator,
  DollarSign,
  AlertCircle,
  CheckCircle2,
  SlidersHorizontal,
  RefreshCw,
  Sparkles,
  ArrowRight,
  ShieldAlert,
  Boxes,
  Truck,
  FolderOpen,
  Tag,
  Download,
} from "lucide-react";
import { bulkUpdatePricesAction } from "@/app/admin/actions";
import { formatCurrency } from "@/lib/format";
import type { Category, Product } from "@/lib/types";

interface CustomSupplierItem {
  id: string;
  name: string;
  categoryType?: string;
  type?: string;
}

interface PricingEngineProps {
  products: Product[];
  categories: Category[];
  customSuppliers?: CustomSupplierItem[];
}

export function PricingEngine({
  products,
  categories,
  customSuppliers = [],
}: PricingEngineProps) {
  const [isPending, startTransition] = useTransition();

  // Scope selection
  const [scope, setScope] = useState<"all" | "supplier" | "category" | "brand">("all");
  const [scopeValue, setScopeValue] = useState<string>("");

  // Adjustment mode & targets
  const [target, setTarget] = useState<"both" | "retail" | "wholesale">("both");
  const [mode, setMode] = useState<"percentage" | "cost_multiplier">("percentage");

  // Inputs
  const [retailPercent, setRetailPercent] = useState<number>(10);
  const [wholesalePercent, setWholesalePercent] = useState<number>(10);
  const [retailMultiplier, setRetailMultiplier] = useState<number>(2.0);
  const [wholesaleMultiplier, setWholesaleMultiplier] = useState<number>(1.15);
  const [rounding, setRounding] = useState<"100" | "50" | "1000" | "none">("100");

  // Confirmation & Feedback
  const [isConfirmOpen, setIsConfirmOpen] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  // Available brands in the catalog
  const availableBrands = useMemo(() => {
    return [
      "Total",
      "Wadfow",
      "Medicube",
      "Skin1004",
      "Dr. Althea",
      "Celimax",
      "Karseell",
    ];
  }, []);

  // Built-in suppliers + any custom suppliers
  const allSuppliers = useMemo(() => {
    return [
      { id: "total_tools", name: "Total Tools Oficial Paraguay", type: "Herramientas" },
      { id: "atacado_usa", name: "Atacado USA", type: "Cosméticos & K-Beauty" },
      ...customSuppliers.map((s) => ({
        id: s.id,
        name: s.name,
        type: s.type || s.categoryType || "General",
      })),
    ];
  }, [customSuppliers]);

  // Main parent categories
  const mainCategories = useMemo(() => {
    return categories.filter((c) => !c.parentId);
  }, [categories]);

  // Filter products by scope
  const targetProducts = useMemo(() => {
    return products.filter((p) => {
      if (scope === "all") return true;

      if (scope === "category" && scopeValue) {
        const isDirect = p.categoryId === scopeValue;
        const parentCat = categories.find((c) => c.id === p.categoryId);
        const isChild = parentCat?.parentId === scopeValue;
        return isDirect || isChild;
      }

      if (scope === "brand" && scopeValue) {
        const b = scopeValue.toUpperCase();
        const titleUpper = p.title.toUpperCase();
        const tagsUpper = (p.tags || []).map((t) => t.toUpperCase());
        return titleUpper.includes(b) || tagsUpper.some((t) => t.includes(b));
      }

      if (scope === "supplier" && scopeValue) {
        const supVal = scopeValue.toLowerCase();
        const titleUpper = p.title.toUpperCase();
        const tagsUpper = (p.tags || []).map((t) => t.toUpperCase());
        const cat = categories.find((c) => c.id === p.categoryId);
        const catSlug = (cat?.slug || "").toLowerCase();

        if (supVal === "total_tools") {
          return (
            titleUpper.includes("TOTAL") ||
            titleUpper.includes("WADFOW") ||
            catSlug.includes("herramienta") ||
            tagsUpper.includes("HERRAMIENTAS")
          );
        }
        if (supVal === "atacado_usa") {
          return (
            catSlug.includes("cosmet") ||
            catSlug.includes("capilar") ||
            ["MEDICUBE", "SKIN1004", "CELIMAX", "DR. ALTHEA", "DR ALTHEA", "KARSEELL"].some((b) =>
              titleUpper.includes(b)
            )
          );
        }
        return (
          titleUpper.includes(supVal.toUpperCase()) ||
          tagsUpper.some((t) => t.includes(supVal.toUpperCase()))
        );
      }

      return true;
    });
  }, [products, categories, scope, scopeValue]);

  // Rounding helper
  const applyRound = (val: number) => {
    if (rounding === "100") return Math.round(val / 100) * 100;
    if (rounding === "50") return Math.round(val / 50) * 50;
    if (rounding === "1000") return Math.round(val / 1000) * 1000;
    return Math.round(val);
  };

  // Compute simulated prices for each target product
  const simulatedProducts = useMemo(() => {
    return targetProducts.map((p) => {
      const currentRetail = p.retailPrice;
      const currentWholesale = p.wholesalePrice || Math.round(p.retailPrice * 0.75);

      // Base purchase cost: retail / 2
      const estimatedCost = Math.round(currentRetail / 2);

      let newRetail = currentRetail;
      let newWholesale = currentWholesale;

      if (mode === "percentage") {
        if (target === "retail" || target === "both") {
          newRetail = applyRound(currentRetail * (1 + retailPercent / 100));
        }
        if (target === "wholesale" || target === "both") {
          newWholesale = applyRound(currentWholesale * (1 + wholesalePercent / 100));
        }
      } else if (mode === "cost_multiplier") {
        if (target === "retail" || target === "both") {
          newRetail = applyRound(estimatedCost * retailMultiplier);
        }
        if (target === "wholesale" || target === "both") {
          newWholesale = applyRound(estimatedCost * wholesaleMultiplier);
        }
      }

      if (newWholesale > newRetail) {
        newWholesale = Math.round(newRetail * 0.85);
      }
      newRetail = Math.max(100, newRetail);
      newWholesale = Math.max(100, newWholesale);

      const mlRefPrice = Math.round((newRetail * 1.08) / 100) * 100;
      const retailProfit = newRetail - estimatedCost;
      const wholesaleProfit = newWholesale - estimatedCost;

      return {
        product: p,
        estimatedCost,
        currentRetail,
        currentWholesale,
        newRetail,
        newWholesale,
        mlRefPrice,
        retailProfit,
        wholesaleProfit,
      };
    });
  }, [
    targetProducts,
    mode,
    target,
    retailPercent,
    wholesalePercent,
    retailMultiplier,
    wholesaleMultiplier,
    rounding,
  ]);

  // Aggregated KPIs
  const currentRetailTotal = useMemo(
    () => simulatedProducts.reduce((sum, item) => sum + item.currentRetail, 0),
    [simulatedProducts]
  );
  const newRetailTotal = useMemo(
    () => simulatedProducts.reduce((sum, item) => sum + item.newRetail, 0),
    [simulatedProducts]
  );
  const currentWholesaleTotal = useMemo(
    () => simulatedProducts.reduce((sum, item) => sum + item.currentWholesale, 0),
    [simulatedProducts]
  );
  const newWholesaleTotal = useMemo(
    () => simulatedProducts.reduce((sum, item) => sum + item.newWholesale, 0),
    [simulatedProducts]
  );

  const avgRetailDiff =
    simulatedProducts.length > 0
      ? (newRetailTotal - currentRetailTotal) / simulatedProducts.length
      : 0;

  // Sample items to show in preview table
  const sampleItems = useMemo(() => {
    return simulatedProducts.slice(0, 6);
  }, [simulatedProducts]);

  // Execute update
  const handleExecuteUpdate = () => {
    setIsConfirmOpen(false);
    setErrorMessage(null);
    setSuccessMessage(null);

    startTransition(async () => {
      try {
        const res = await bulkUpdatePricesAction({
          scope,
          scopeValue,
          target,
          mode,
          retailPercent,
          wholesalePercent,
          retailMultiplier,
          wholesaleMultiplier,
          rounding,
        });
        setSuccessMessage(res.message);
        setTimeout(() => setSuccessMessage(null), 8000);
      } catch (err: unknown) {
        setErrorMessage((err instanceof Error ? err.message : "Error inesperado") || "Error al actualizar precios");
      }
    });
  };

  // Export CSV of this preview
  const handleExportCsv = () => {
    const headers = [
      "SKU / ID",
      "Producto",
      "Costo Estimado ARS",
      "Precio Minorista Actual",
      "Nuevo Precio Minorista",
      "Precio Mayorista Actual",
      "Nuevo Precio Mayorista",
      "Ref. Mercado Libre",
      "Ganancia Estimada x Unidad",
    ];

    const rows = simulatedProducts.map((item) => [
      item.product.id,
      `"${item.product.title.replace(/"/g, '""')}"`,
      item.estimatedCost,
      item.currentRetail,
      item.newRetail,
      item.currentWholesale,
      item.newWholesale,
      item.mlRefPrice,
      item.retailProfit,
    ]);

    const csvContent = "\uFEFF" + [headers.join(";"), ...rows.map((r) => r.join(";"))].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `ajuste_precios_${scope}_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-8">
      {/* Top Banner */}
      <div className="relative overflow-hidden rounded-3xl bg-zinc-950 p-6 sm:p-8 text-white shadow-xl border border-zinc-800">
        <div className="relative z-10 max-w-3xl">
          <div className="inline-flex items-center gap-2 rounded-full bg-emerald-500/10 border border-emerald-500/30 px-3 py-1 text-xs font-bold text-emerald-400 mb-3">
            <Sparkles className="h-3.5 w-3.5" />
            Estrategia de Precios & Rentabilidad
          </div>
          <h2 className="text-2xl sm:text-3xl font-extrabold tracking-tight text-white">
            Ajustador Masivo de Precios Global & por Proveedor
          </h2>
          <p className="mt-2 text-sm text-zinc-300 leading-relaxed">
            Subí los precios en porcentaje (%) o recalculalos en base a tu <strong>costo de compra de origen</strong> (Paraguay / USA).
            Podés seleccionar todo el catálogo, un proveedor específico (Total Tools, Atacado USA), un rubro o una marca.
            Revisá la simulación en vivo antes de guardar los cambios en la base de datos.
          </p>
        </div>
        <div className="absolute right-0 top-0 h-full w-1/3 bg-gradient-to-l from-emerald-500/10 to-transparent pointer-events-none" />
      </div>

      {/* Messages */}
      {successMessage && (
        <div className="flex items-center gap-3 rounded-2xl bg-emerald-50 p-4 border border-emerald-200 text-emerald-900 shadow-sm animate-in fade-in duration-200">
          <CheckCircle2 className="h-5 w-5 text-emerald-600 shrink-0" />
          <div className="text-sm font-semibold">{successMessage}</div>
        </div>
      )}

      {errorMessage && (
        <div className="flex items-center gap-3 rounded-2xl bg-red-50 p-4 border border-red-200 text-red-900 shadow-sm animate-in fade-in duration-200">
          <AlertCircle className="h-5 w-5 text-red-600 shrink-0" />
          <div className="text-sm font-semibold">{errorMessage}</div>
        </div>
      )}

      {/* Settings Grid */}
      <div className="grid gap-6 lg:grid-cols-3">
        {/* Step 1: Scope */}
        <div className="rounded-2xl border border-zinc-200 bg-white p-6 shadow-xs flex flex-col justify-between">
          <div>
            <div className="flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-zinc-400 mb-3">
              <span className="flex h-5 w-5 items-center justify-center rounded-full bg-zinc-900 text-[10px] text-white">1</span>
              Alcance de Productos
            </div>
            <h3 className="text-base font-bold text-zinc-950 mb-3">
              ¿A qué productos querés aplicar el ajuste?
            </h3>

            <div className="grid grid-cols-2 gap-2 mb-4">
              {[
                { id: "all", label: "Todo el Catálogo", icon: Boxes, count: products.length },
                { id: "supplier", label: "Por Proveedor", icon: Truck },
                { id: "category", label: "Por Rubro", icon: FolderOpen },
                { id: "brand", label: "Por Marca", icon: Tag },
              ].map((opt) => (
                <button
                  key={opt.id}
                  type="button"
                  onClick={() => {
                    setScope(opt.id as typeof scope);
                    if (opt.id === "all") setScopeValue("");
                    else if (opt.id === "supplier") setScopeValue("total_tools");
                    else if (opt.id === "category" && mainCategories[0]) setScopeValue(mainCategories[0].id);
                    else if (opt.id === "brand") setScopeValue("Total");
                  }}
                  className={`flex flex-col items-center justify-center p-3 rounded-xl border text-center transition-all cursor-pointer ${
                    scope === opt.id
                      ? "border-zinc-900 bg-zinc-900 text-white shadow-xs font-bold"
                      : "border-zinc-200 bg-zinc-50/50 hover:bg-zinc-100 text-zinc-700 font-medium"
                  }`}
                >
                  <opt.icon className="h-4 w-4 mb-1" />
                  <span className="text-xs">{opt.label}</span>
                  {opt.count && (
                    <span className="text-[10px] opacity-80 mt-0.5">({opt.count})</span>
                  )}
                </button>
              ))}
            </div>

            {/* Scope Value Dropdown */}
            {scope === "supplier" && (
              <div className="space-y-1.5 pt-2 border-t border-zinc-100">
                <label className="text-xs font-semibold text-zinc-600">Seleccionar Proveedor:</label>
                <select
                  value={scopeValue}
                  onChange={(e) => setScopeValue(e.target.value)}
                  className="w-full h-10 px-3 rounded-xl border border-zinc-300 text-xs font-bold text-zinc-900 outline-none focus:border-zinc-900"
                >
                  {allSuppliers.map((s) => (
                    <option key={s.id} value={s.id}>
                      {s.name} ({s.type})
                    </option>
                  ))}
                </select>
              </div>
            )}

            {scope === "category" && (
              <div className="space-y-1.5 pt-2 border-t border-zinc-100">
                <label className="text-xs font-semibold text-zinc-600">Seleccionar Rubro:</label>
                <select
                  value={scopeValue}
                  onChange={(e) => setScopeValue(e.target.value)}
                  className="w-full h-10 px-3 rounded-xl border border-zinc-300 text-xs font-bold text-zinc-900 outline-none focus:border-zinc-900"
                >
                  {categories.map((c) => (
                    <option key={c.id} value={c.id}>
                      {c.parentId ? "↳ " : ""}{c.name}
                    </option>
                  ))}
                </select>
              </div>
            )}

            {scope === "brand" && (
              <div className="space-y-1.5 pt-2 border-t border-zinc-100">
                <label className="text-xs font-semibold text-zinc-600">Seleccionar Marca:</label>
                <select
                  value={scopeValue}
                  onChange={(e) => setScopeValue(e.target.value)}
                  className="w-full h-10 px-3 rounded-xl border border-zinc-300 text-xs font-bold text-zinc-900 outline-none focus:border-zinc-900"
                >
                  {availableBrands.map((b) => (
                    <option key={b} value={b}>
                      {b}
                    </option>
                  ))}
                </select>
              </div>
            )}
          </div>

          <div className="mt-4 pt-3 border-t border-zinc-100 flex items-center justify-between text-xs text-zinc-500">
            <span>Productos alcanzados:</span>
            <span className="font-extrabold text-zinc-900 text-sm">
              {targetProducts.length.toLocaleString("es-AR")}
            </span>
          </div>
        </div>

        {/* Step 2: Calculation Mode & Percentages */}
        <div className="rounded-2xl border border-zinc-200 bg-white p-6 shadow-xs flex flex-col justify-between">
          <div>
            <div className="flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-zinc-400 mb-3">
              <span className="flex h-5 w-5 items-center justify-center rounded-full bg-zinc-900 text-[10px] text-white">2</span>
              Método de Ajuste
            </div>

            {/* Target selector: Retail, Wholesale, Both */}
            <div className="space-y-1.5 mb-4">
              <label className="text-xs font-semibold text-zinc-600">Precios a modificar:</label>
              <div className="grid grid-cols-3 gap-1.5 p-1 bg-zinc-100 rounded-xl">
                {[
                  { id: "both", label: "Ambos" },
                  { id: "retail", label: "Minorista" },
                  { id: "wholesale", label: "Mayorista" },
                ].map((t) => (
                  <button
                    key={t.id}
                    type="button"
                    onClick={() => setTarget(t.id as typeof target)}
                    className={`py-1.5 text-xs font-bold rounded-lg transition-all cursor-pointer ${
                      target === t.id
                        ? "bg-white text-zinc-950 shadow-xs"
                        : "text-zinc-600 hover:text-zinc-900"
                    }`}
                  >
                    {t.label}
                  </button>
                ))}
              </div>
            </div>

            {/* Mode selector */}
            <div className="space-y-1.5 mb-4">
              <label className="text-xs font-semibold text-zinc-600">Tipo de cálculo:</label>
              <div className="grid grid-cols-2 gap-2">
                <button
                  type="button"
                  onClick={() => setMode("percentage")}
                  className={`p-2.5 rounded-xl border text-left transition-all cursor-pointer ${
                    mode === "percentage"
                      ? "border-emerald-600 bg-emerald-50/50 text-emerald-950 font-bold"
                      : "border-zinc-200 bg-white text-zinc-600 font-medium"
                  }`}
                >
                  <div className="flex items-center gap-1.5 text-xs">
                    <Percent className="h-3.5 w-3.5 text-emerald-600" />
                    <span>Porcentaje (%)</span>
                  </div>
                  <p className="text-[10px] text-zinc-500 mt-1">
                    Aumenta +X% sobre precio actual
                  </p>
                </button>

                <button
                  type="button"
                  onClick={() => setMode("cost_multiplier")}
                  className={`p-2.5 rounded-xl border text-left transition-all cursor-pointer ${
                    mode === "cost_multiplier"
                      ? "border-emerald-600 bg-emerald-50/50 text-emerald-950 font-bold"
                      : "border-zinc-200 bg-white text-zinc-600 font-medium"
                  }`}
                >
                  <div className="flex items-center gap-1.5 text-xs">
                    <Calculator className="h-3.5 w-3.5 text-emerald-600" />
                    <span>Multiplicador Costo</span>
                  </div>
                  <p className="text-[10px] text-zinc-500 mt-1">
                    Calcula Costo × Margen
                  </p>
                </button>
              </div>
            </div>

            {/* Inputs based on mode */}
            {mode === "percentage" ? (
              <div className="space-y-3 pt-2 border-t border-zinc-100">
                {(target === "retail" || target === "both") && (
                  <div>
                    <div className="flex items-center justify-between mb-1.5">
                      <label className="text-xs font-semibold text-zinc-700">
                        Aumento Minorista:
                      </label>
                      <span className="text-xs font-bold text-emerald-700">
                        +{retailPercent}%
                      </span>
                    </div>
                    <div className="flex items-center gap-2">
                      <input
                        type="number"
                        step={1}
                        value={retailPercent}
                        onChange={(e) => setRetailPercent(Number(e.target.value))}
                        className="w-20 h-9 px-2 text-center rounded-lg border border-zinc-300 font-bold text-xs"
                      />
                      <div className="flex gap-1 flex-1">
                        {[5, 10, 15, 20, 25].map((pct) => (
                          <button
                            key={pct}
                            type="button"
                            onClick={() => setRetailPercent(pct)}
                            className={`flex-1 py-1 rounded-md text-[11px] font-semibold border ${
                              retailPercent === pct
                                ? "bg-emerald-600 text-white border-emerald-600"
                                : "bg-zinc-50 hover:bg-zinc-100 border-zinc-200 text-zinc-700"
                            }`}
                          >
                            +{pct}%
                          </button>
                        ))}
                      </div>
                    </div>
                  </div>
                )}

                {(target === "wholesale" || target === "both") && (
                  <div>
                    <div className="flex items-center justify-between mb-1.5">
                      <label className="text-xs font-semibold text-zinc-700">
                        Aumento Mayorista:
                      </label>
                      <span className="text-xs font-bold text-amber-700">
                        +{wholesalePercent}%
                      </span>
                    </div>
                    <div className="flex items-center gap-2">
                      <input
                        type="number"
                        step={1}
                        value={wholesalePercent}
                        onChange={(e) => setWholesalePercent(Number(e.target.value))}
                        className="w-20 h-9 px-2 text-center rounded-lg border border-zinc-300 font-bold text-xs"
                      />
                      <div className="flex gap-1 flex-1">
                        {[5, 10, 15, 20].map((pct) => (
                          <button
                            key={pct}
                            type="button"
                            onClick={() => setWholesalePercent(pct)}
                            className={`flex-1 py-1 rounded-md text-[11px] font-semibold border ${
                              wholesalePercent === pct
                                ? "bg-amber-600 text-white border-amber-600"
                                : "bg-zinc-50 hover:bg-zinc-100 border-zinc-200 text-zinc-700"
                            }`}
                          >
                            +{pct}%
                          </button>
                        ))}
                      </div>
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div className="space-y-3 pt-2 border-t border-zinc-100">
                {(target === "retail" || target === "both") && (
                  <div>
                    <div className="flex items-center justify-between mb-1.5">
                      <label className="text-xs font-semibold text-zinc-700">
                        Multiplicador Minorista (PVP):
                      </label>
                      <span className="text-xs font-bold text-emerald-700">
                        {retailMultiplier}x costo (+{Math.round((retailMultiplier - 1) * 100)}%)
                      </span>
                    </div>
                    <div className="flex items-center gap-2">
                      <input
                        type="number"
                        step={0.05}
                        min={1}
                        value={retailMultiplier}
                        onChange={(e) => setRetailMultiplier(Number(e.target.value))}
                        className="w-20 h-9 px-2 text-center rounded-lg border border-zinc-300 font-bold text-xs"
                      />
                      <div className="flex gap-1 flex-1">
                        {[1.8, 2.0, 2.2, 2.5].map((mult) => (
                          <button
                            key={mult}
                            type="button"
                            onClick={() => setRetailMultiplier(mult)}
                            className={`flex-1 py-1 rounded-md text-[11px] font-semibold border ${
                              retailMultiplier === mult
                                ? "bg-emerald-600 text-white border-emerald-600"
                                : "bg-zinc-50 hover:bg-zinc-100 border-zinc-200 text-zinc-700"
                            }`}
                          >
                            {mult}x
                          </button>
                        ))}
                      </div>
                    </div>
                  </div>
                )}

                {(target === "wholesale" || target === "both") && (
                  <div>
                    <div className="flex items-center justify-between mb-1.5">
                      <label className="text-xs font-semibold text-zinc-700">
                        Multiplicador Mayorista (B2B):
                      </label>
                      <span className="text-xs font-bold text-amber-700">
                        {wholesaleMultiplier}x costo (+{Math.round((wholesaleMultiplier - 1) * 100)}%)
                      </span>
                    </div>
                    <div className="flex items-center gap-2">
                      <input
                        type="number"
                        step={0.05}
                        min={1}
                        value={wholesaleMultiplier}
                        onChange={(e) => setWholesaleMultiplier(Number(e.target.value))}
                        className="w-20 h-9 px-2 text-center rounded-lg border border-zinc-300 font-bold text-xs"
                      />
                      <div className="flex gap-1 flex-1">
                        {[1.10, 1.15, 1.20, 1.25].map((mult) => (
                          <button
                            key={mult}
                            type="button"
                            onClick={() => setWholesaleMultiplier(mult)}
                            className={`flex-1 py-1 rounded-md text-[11px] font-semibold border ${
                              wholesaleMultiplier === mult
                                ? "bg-amber-600 text-white border-amber-600"
                                : "bg-zinc-50 hover:bg-zinc-100 border-zinc-200 text-zinc-700"
                            }`}
                          >
                            {mult}x
                          </button>
                        ))}
                      </div>
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>

          <div className="mt-4 pt-3 border-t border-zinc-100 flex items-center justify-between text-xs text-zinc-500">
            <span>Objetivo seleccionado:</span>
            <span className="font-bold text-zinc-900 uppercase">
              {target === "both" ? "Minorista + Mayorista" : target}
            </span>
          </div>
        </div>

        {/* Step 3: Rounding & Action */}
        <div className="rounded-2xl border border-zinc-200 bg-white p-6 shadow-xs flex flex-col justify-between">
          <div>
            <div className="flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-zinc-400 mb-3">
              <span className="flex h-5 w-5 items-center justify-center rounded-full bg-zinc-900 text-[10px] text-white">3</span>
              Redondeo & Ejecución
            </div>
            <h3 className="text-base font-bold text-zinc-950 mb-3">
              Redondeo de Precios Comerciales
            </h3>

            <div className="grid grid-cols-2 gap-2 mb-4">
              {[
                { id: "100", label: "A $100", desc: "$14.380 → $14.400" },
                { id: "50", label: "A $50", desc: "$14.320 → $14.350" },
                { id: "1000", label: "A $1.000", desc: "$14.380 → $14.000" },
                { id: "none", label: "Exacto", desc: "Sin redondear" },
              ].map((r) => (
                <button
                  key={r.id}
                  type="button"
                  onClick={() => setRounding(r.id as typeof rounding)}
                  className={`p-2.5 rounded-xl border text-left transition-all cursor-pointer ${
                    rounding === r.id
                      ? "border-zinc-900 bg-zinc-900 text-white font-bold"
                      : "border-zinc-200 bg-zinc-50/50 hover:bg-zinc-100 text-zinc-700"
                  }`}
                >
                  <p className="text-xs">{r.label}</p>
                  <p className="text-[10px] opacity-75 mt-0.5">{r.desc}</p>
                </button>
              ))}
            </div>

            <div className="rounded-xl bg-amber-50 p-3 border border-amber-200/80 mb-4">
              <div className="flex items-start gap-2">
                <ShieldAlert className="h-4 w-4 text-amber-600 mt-0.5 shrink-0" />
                <p className="text-[11px] text-amber-900 leading-relaxed">
                  Esta acción actualizará directamente los precios en la base de datos de Supabase para los{" "}
                  <strong>{targetProducts.length.toLocaleString("es-AR")} productos seleccionados</strong>.
                  La tienda y el canal mayorista se actualizarán inmediatamente.
                </p>
              </div>
            </div>
          </div>

          <div className="space-y-2 pt-2 border-t border-zinc-100">
            <button
              type="button"
              disabled={isPending || targetProducts.length === 0}
              onClick={() => setIsConfirmOpen(true)}
              className="w-full h-11 rounded-xl bg-zinc-950 text-white hover:bg-zinc-800 font-bold text-xs shadow-md transition-all flex items-center justify-center gap-2 cursor-pointer disabled:opacity-50"
            >
              {isPending ? (
                <>
                  <RefreshCw className="h-4 w-4 animate-spin" />
                  Actualizando {targetProducts.length} productos...
                </>
              ) : (
                <>
                  <TrendingUp className="h-4 w-4 text-emerald-400" />
                  Aplicar Ajuste a {targetProducts.length.toLocaleString("es-AR")} Productos
                </>
              )}
            </button>

            <button
              type="button"
              onClick={handleExportCsv}
              disabled={targetProducts.length === 0}
              className="w-full h-9 rounded-xl border border-zinc-200 bg-white hover:bg-zinc-50 text-zinc-700 font-semibold text-xs transition-colors flex items-center justify-center gap-1.5 cursor-pointer disabled:opacity-50"
            >
              <Download className="h-3.5 w-3.5 text-zinc-500" />
              Descargar Simulación en CSV / Excel
            </button>
          </div>
        </div>
      </div>

      {/* Financial Impact KPIs */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <div className="rounded-2xl border border-zinc-200 bg-white p-5 shadow-xs">
          <span className="text-xs font-semibold text-zinc-400 uppercase tracking-wider">
            Productos Alcanzados
          </span>
          <p className="mt-2 text-2xl font-black text-zinc-950">
            {targetProducts.length.toLocaleString("es-AR")}
          </p>
          <p className="text-[11px] text-zinc-500 mt-1">
            de un total de {products.length.toLocaleString("es-AR")} en el catálogo
          </p>
        </div>

        <div className="rounded-2xl border border-zinc-200 bg-white p-5 shadow-xs">
          <span className="text-xs font-semibold text-zinc-400 uppercase tracking-wider">
            Valor Catálogo Minorista
          </span>
          <div className="flex items-baseline gap-2 mt-2">
            <span className="text-lg font-bold text-zinc-400 line-through">
              {formatCurrency(currentRetailTotal)}
            </span>
            <span className="text-xl font-black text-emerald-700">
              {formatCurrency(newRetailTotal)}
            </span>
          </div>
          <p className="text-[11px] text-emerald-700 font-semibold mt-1">
            {newRetailTotal >= currentRetailTotal ? "+" : ""}
            {formatCurrency(newRetailTotal - currentRetailTotal)} de valuación
          </p>
        </div>

        <div className="rounded-2xl border border-zinc-200 bg-white p-5 shadow-xs">
          <span className="text-xs font-semibold text-zinc-400 uppercase tracking-wider">
            Valor Catálogo Mayorista
          </span>
          <div className="flex items-baseline gap-2 mt-2">
            <span className="text-lg font-bold text-zinc-400 line-through">
              {formatCurrency(currentWholesaleTotal)}
            </span>
            <span className="text-xl font-black text-amber-700">
              {formatCurrency(newWholesaleTotal)}
            </span>
          </div>
          <p className="text-[11px] text-amber-700 font-semibold mt-1">
            {newWholesaleTotal >= currentWholesaleTotal ? "+" : ""}
            {formatCurrency(newWholesaleTotal - currentWholesaleTotal)} en canal B2B
          </p>
        </div>

        <div className="rounded-2xl border border-zinc-200 bg-white p-5 shadow-xs">
          <span className="text-xs font-semibold text-zinc-400 uppercase tracking-wider">
            Variación Promedio / Producto
          </span>
          <p className="mt-2 text-2xl font-black text-zinc-950">
            {avgRetailDiff >= 0 ? "+" : ""}
            {formatCurrency(Math.round(avgRetailDiff))}
          </p>
          <p className="text-[11px] text-zinc-500 mt-1">
            impacto promedio por artículo minorista
          </p>
        </div>
      </div>

      {/* Live Sample Simulation Table */}
      <div className="rounded-2xl border border-zinc-200 bg-white shadow-xs overflow-hidden">
        <div className="p-5 border-b border-zinc-200 bg-zinc-50 flex items-center justify-between">
          <div>
            <h3 className="font-bold text-sm text-zinc-900 flex items-center gap-2">
              <SlidersHorizontal className="h-4 w-4 text-emerald-600" />
              Simulación en Tiempo Real (Muestra de 6 Productos)
            </h3>
            <p className="text-xs text-zinc-500 mt-0.5">
              Así impactará tu fórmula en los precios minoristas, mayoristas y comparativa de Mercado Libre.
            </p>
          </div>
          <span className="text-xs font-bold text-zinc-500 bg-white border border-zinc-200 px-2.5 py-1 rounded-lg">
            Redondeo: {rounding === "none" ? "Sin redondear" : `a $${rounding}`}
          </span>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full min-w-[900px] text-left text-xs">
            <thead className="bg-zinc-100/70 border-b border-zinc-200 text-zinc-500 font-bold uppercase tracking-wider">
              <tr>
                <th className="px-5 py-3">Producto</th>
                <th className="px-4 py-3">Costo Origen</th>
                <th className="px-4 py-3">Precio Minorista</th>
                <th className="px-4 py-3">Precio Mayorista (B2B)</th>
                <th className="px-4 py-3">Ref. Mercado Libre</th>
                <th className="px-4 py-3">Margen Ganancia Unit.</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-zinc-100">
              {sampleItems.map((item) => {
                const retailDiff = item.newRetail - item.currentRetail;
                const wholesaleDiff = item.newWholesale - item.currentWholesale;

                return (
                  <tr key={item.product.id} className="hover:bg-zinc-50/80 transition-colors">
                    <td className="px-5 py-3.5">
                      <div className="flex items-center gap-3">
                        <img
                          src={item.product.imageUrl || "/placeholder-product.svg"}
                          alt={item.product.title}
                          className="h-10 w-10 rounded-lg object-contain bg-white p-1 border border-zinc-200 shrink-0"
                        />
                        <div className="min-w-0 max-w-xs">
                          <p className="font-bold text-zinc-900 truncate">
                            {item.product.title}
                          </p>
                          <p className="text-[10px] text-zinc-400 truncate">
                            {item.product.categoryName || "Catálogo MYA"}
                          </p>
                        </div>
                      </div>
                    </td>

                    <td className="px-4 py-3.5">
                      <span className="font-semibold text-zinc-600">
                        {formatCurrency(item.estimatedCost)}
                      </span>
                      <p className="text-[10px] text-zinc-400">origen est.</p>
                    </td>

                    <td className="px-4 py-3.5">
                      <div className="flex items-baseline gap-1.5">
                        <span className="line-through text-zinc-400">
                          {formatCurrency(item.currentRetail)}
                        </span>
                        <span className="font-black text-emerald-700 text-sm">
                          {formatCurrency(item.newRetail)}
                        </span>
                      </div>
                      {retailDiff !== 0 && (
                        <span className="text-[10px] font-bold text-emerald-600">
                          {retailDiff > 0 ? "+" : ""}{formatCurrency(retailDiff)}
                        </span>
                      )}
                    </td>

                    <td className="px-4 py-3.5">
                      <div className="flex items-baseline gap-1.5">
                        <span className="line-through text-zinc-400">
                          {formatCurrency(item.currentWholesale)}
                        </span>
                        <span className="font-black text-amber-700 text-sm">
                          {formatCurrency(item.newWholesale)}
                        </span>
                      </div>
                      {wholesaleDiff !== 0 && (
                        <span className="text-[10px] font-bold text-amber-600">
                          {wholesaleDiff > 0 ? "+" : ""}{formatCurrency(wholesaleDiff)}
                        </span>
                      )}
                    </td>

                    <td className="px-4 py-3.5">
                      <span className="text-zinc-500 line-through">
                        {formatCurrency(item.mlRefPrice)}
                      </span>
                      <span className="ml-1.5 rounded-full bg-emerald-50 px-1.5 py-0.5 text-[9px] font-bold text-emerald-700 border border-emerald-200">
                        -8% vs ML
                      </span>
                    </td>

                    <td className="px-4 py-3.5">
                      <p className="font-bold text-emerald-700">
                        +{formatCurrency(item.retailProfit)}{" "}
                        <span className="text-[10px] text-zinc-400 font-normal">PVP</span>
                      </p>
                      <p className="text-[10px] font-semibold text-amber-700">
                        +{formatCurrency(item.wholesaleProfit)} B2B
                      </p>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {/* Confirmation Safety Modal */}
      {isConfirmOpen && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-zinc-950/60 backdrop-blur-sm animate-in fade-in duration-150"
          role="dialog"
          aria-modal="true"
        >
          <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl border border-zinc-200 animate-in zoom-in-95 duration-150">
            <div className="flex items-center gap-3 text-amber-600 mb-4">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-amber-100">
                <AlertCircle className="h-5 w-5" />
              </div>
              <div>
                <h3 className="text-base font-bold text-zinc-950">Confirmar Ajuste Masivo</h3>
                <p className="text-xs text-zinc-500">Esta acción impactará en el catálogo real</p>
              </div>
            </div>

            <p className="text-xs text-zinc-650 leading-relaxed mb-4">
              ¿Estás seguro de que querés actualizar los precios de los{" "}
              <strong className="text-zinc-900">{targetProducts.length.toLocaleString("es-AR")} productos</strong>{" "}
              seleccionados?
              <br />
              <br />
              • Modo: <strong>{mode === "percentage" ? "Porcentaje (%)" : "Multiplicador de Costo"}</strong>
              <br />
              • Minorista: <strong>{mode === "percentage" ? `+${retailPercent}%` : `${retailMultiplier}x Costo`}</strong>
              <br />
              • Mayorista: <strong>{mode === "percentage" ? `+${wholesalePercent}%` : `${wholesaleMultiplier}x Costo`}</strong>
              <br />
              • Redondeo: <strong>{rounding === "none" ? "Sin redondear" : `Múltiplos de $${rounding}`}</strong>
            </p>

            <div className="flex items-center justify-end gap-2 pt-3 border-t border-zinc-100">
              <button
                type="button"
                onClick={() => setIsConfirmOpen(false)}
                className="px-4 py-2 rounded-xl text-xs font-semibold text-zinc-600 hover:bg-zinc-100 transition cursor-pointer"
              >
                Cancelar
              </button>
              <button
                type="button"
                onClick={handleExecuteUpdate}
                className="px-5 py-2 rounded-xl bg-zinc-950 hover:bg-zinc-800 text-white text-xs font-bold shadow-xs transition cursor-pointer"
              >
                Sí, aplicar actualización
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useTransition, useMemo } from "react";
import { useRouter } from "next/navigation";
import { ProductEditor } from "./product-editor";
import {
  Search,
  Package,
  Edit,
  Trash2,
  ExternalLink,
  CheckCircle2,
  XCircle,
  AlertTriangle,
  RefreshCw,
  TrendingUp,
  DollarSign,
  Truck,
  Layers,
  ChevronLeft,
  ChevronRight,
  Copy,
  Check,
  Percent,
  Eye,
  EyeOff,
  Globe,
  Boxes,
  Plus,
  Link as LinkIcon,
} from "lucide-react";
import { formatCurrency, formatDate } from "@/lib/format";
import type { Category, Product, StockLog } from "@/lib/types";
import {
  toggleProductActiveAction,
  toggleProductSupplierAvailabilityAction,
  checkSingleProductSupplierStockAction,
  triggerBatchSupplierSyncAction,
  quickUpdateProductPriceAction,
  bulkUpdateProductStatusAction,
  bulkAdjustPricesAction,
  deleteProductAction,
  quickUpdateSupplierLinkAction,
} from "@/app/admin/actions";

interface ProductControlCenterProps {
  products: Product[];
  categories: Category[];
  stockLogs: StockLog[];
  onOpenCreateProduct?: () => void;
}

export function ProductControlCenter({
  products,
  categories,
  stockLogs,
  onOpenCreateProduct,
}: ProductControlCenterProps) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();

  // Filters state
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<"all" | "active" | "paused">("all");
  const [availabilityFilter, setAvailabilityFilter] = useState<
    "all" | "in_stock" | "out_of_stock" | "supplier_available" | "supplier_paused" | "own_stock"
  >("all");
  const [fulfillmentFilter, setFulfillmentFilter] = useState<"all" | "supplier" | "own_stock">("all");
  const [supplierLinkFilter, setSupplierLinkFilter] = useState<"all" | "with_link" | "without_link">("all");
  const [categoryFilter, setCategoryFilter] = useState("");
  const [brandFilter, setBrandFilter] = useState("");
  const [sortBy, setSortBy] = useState<"name" | "price_asc" | "price_desc" | "status" | "recent">("recent");

  // Pagination state
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);

  // Selection state for bulk operations
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  // Modals state
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [quickPriceProduct, setQuickPriceProduct] = useState<Product | null>(null);
  const [quickSupplierProduct, setQuickSupplierProduct] = useState<Product | null>(null);
  const [copiedSupplierLink, setCopiedSupplierLink] = useState<string | null>(null);
  const [quickRetailPrice, setQuickRetailPrice] = useState<number>(0);
  const [quickWholesalePrice, setQuickWholesalePrice] = useState<number>(0);
  const [isBulkPriceModalOpen, setIsBulkPriceModalOpen] = useState(false);
  const [bulkPriceType, setBulkPriceType] = useState<"percentage" | "fixed_markup">("percentage");
  const [bulkPriceAmount, setBulkPriceAmount] = useState<number>(10);
  const [showStockAudit, setShowStockAudit] = useState(false);

  // Live supplier verification state
  const [verifyingId, setVerifyingId] = useState<string | null>(null);
  const [verificationFeedback, setVerificationFeedback] = useState<Record<string, { message: string; ok: boolean }>>({});
  const [isBatchSyncRunning, setIsBatchSyncRunning] = useState(false);
  const [batchSyncReport, setBatchSyncReport] = useState<{
    total: number;
    checked: number;
    inStock: number;
    outOfStock: number;
    errors: number;
    timestamp: string;
  } | null>(null);

  // UI feedback notifications
  const [toastMessage, setToastMessage] = useState<{ text: string; type: "success" | "error" | "info" } | null>(null);
  const [copiedSku, setCopiedSku] = useState<string | null>(null);

  const showToast = (text: string, type: "success" | "error" | "info" = "success") => {
    setToastMessage({ text, type });
    setTimeout(() => setToastMessage(null), 4000);
  };

  // Distinct Brands
  const distinctBrands = useMemo(() => {
    const set = new Set<string>();
    for (const p of products) {
      if (p.brand) set.add(p.brand.trim());
    }
    return Array.from(set).sort();
  }, [products]);

  // Main Categories
  const mainCategories = useMemo(() => {
    return categories.filter((c) => !c.parentId);
  }, [categories]);

  // KPI Metrics (computed in a single O(N) pass without extra array allocations)
  const stats = useMemo(() => {
    let active = 0;
    let supplier = 0;
    let supplierAvailable = 0;
    let withSupplierLink = 0;
    const total = products.length;

    for (let i = 0; i < total; i++) {
      const p = products[i];
      if (p.active !== false) active++;
      if (p.fulfillmentMode === "supplier") {
        supplier++;
        if (p.supplierAvailable) supplierAvailable++;
      }
      if (p.sourceUrl) withSupplierLink++;
    }
    const paused = total - active;
    const ownStock = total - supplier;
    const supplierPaused = supplier - supplierAvailable;
    const withoutSupplierLink = total - withSupplierLink;

    return {
      total,
      active,
      paused,
      supplier,
      ownStock,
      supplierAvailable,
      supplierPaused,
      withSupplierLink,
      withoutSupplierLink,
      activeRate: total > 0 ? Math.round((active / total) * 100) : 0,
    };
  }, [products]);

  // Filter & Sort Logic
  const filteredProducts = useMemo(() => {
    const term = search.trim().toLowerCase();

    return products
      .filter((p) => {
        // Search
        if (term) {
          const matchTitle = p.title.toLowerCase().includes(term);
          const matchSku = p.sku ? p.sku.toLowerCase().includes(term) : false;
          const matchBrand = p.brand ? p.brand.toLowerCase().includes(term) : false;
          const matchModel = p.model ? p.model.toLowerCase().includes(term) : false;
          const matchTags = p.tags ? p.tags.some((t) => t.toLowerCase().includes(term)) : false;
          if (!matchTitle && !matchSku && !matchBrand && !matchModel && !matchTags) return false;
        }

        // Shop Status (Active / Paused)
        if (statusFilter === "active" && p.active === false) return false;
        if (statusFilter === "paused" && p.active !== false) return false;

        // Supplier Link Filter
        if (supplierLinkFilter === "with_link" && !p.sourceUrl) return false;
        if (supplierLinkFilter === "without_link" && p.sourceUrl) return false;

        // Availability Filter
        if (availabilityFilter === "supplier_available" && !(p.fulfillmentMode === "supplier" && p.supplierAvailable)) return false;
        if (availabilityFilter === "supplier_paused" && !(p.fulfillmentMode === "supplier" && !p.supplierAvailable)) return false;
        if (availabilityFilter === "own_stock" && p.fulfillmentMode === "supplier") return false;
        if (availabilityFilter === "in_stock") {
          const isIn = p.fulfillmentMode === "supplier" ? p.supplierAvailable : (Number(p.stock) > 0 && p.stockVerifiedAt);
          if (!isIn) return false;
        }
        if (availabilityFilter === "out_of_stock") {
          const isOut = p.fulfillmentMode === "supplier" ? !p.supplierAvailable : (!p.stockVerifiedAt || Number(p.stock) <= 0);
          if (!isOut) return false;
        }

        // Fulfillment mode
        if (fulfillmentFilter === "supplier" && p.fulfillmentMode !== "supplier") return false;
        if (fulfillmentFilter === "own_stock" && p.fulfillmentMode === "supplier") return false;

        // Category Filter
        if (categoryFilter) {
          if (p.categoryId !== categoryFilter) {
            const cat = categories.find((c) => c.id === p.categoryId);
            if (!cat || cat.parentId !== categoryFilter) return false;
          }
        }

        // Brand Filter
        if (brandFilter && p.brand !== brandFilter) return false;

        return true;
      })
      .sort((a, b) => {
        if (sortBy === "name") return a.title.localeCompare(b.title);
        if (sortBy === "price_asc") return a.retailPrice - b.retailPrice;
        if (sortBy === "price_desc") return b.retailPrice - a.retailPrice;
        if (sortBy === "status") {
          const aVal = (a.active !== false ? 2 : 0) + (a.supplierAvailable ? 1 : 0);
          const bVal = (b.active !== false ? 2 : 0) + (b.supplierAvailable ? 1 : 0);
          return bVal - aVal;
        }
        return 0; // default recent/original
      });
  }, [products, search, statusFilter, availabilityFilter, fulfillmentFilter, categoryFilter, brandFilter, sortBy, categories]);

  // Pagination calculation
  const totalPages = Math.max(1, Math.ceil(filteredProducts.length / pageSize));
  const currentPage = Math.min(page, totalPages);
  const paginatedProducts = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return filteredProducts.slice(start, start + pageSize);
  }, [filteredProducts, currentPage, pageSize]);

  // Selection handlers
  const isAllPageSelected = paginatedProducts.length > 0 && paginatedProducts.every((p) => selectedIds.includes(p.id));

  const toggleSelectAllPage = () => {
    if (isAllPageSelected) {
      const pageIds = new Set(paginatedProducts.map((p) => p.id));
      setSelectedIds(selectedIds.filter((id) => !pageIds.has(id)));
    } else {
      const newSet = new Set([...selectedIds, ...paginatedProducts.map((p) => p.id)]);
      setSelectedIds(Array.from(newSet));
    }
  };

  const toggleSelectProduct = (id: string) => {
    if (selectedIds.includes(id)) {
      setSelectedIds(selectedIds.filter((item) => item !== id));
    } else {
      setSelectedIds([...selectedIds, id]);
    }
  };

  // Quick Action: Toggle Active (Pause / Publish in shop)
  const handleToggleActive = (product: Product) => {
    const nextState = product.active === false ? true : false;
    startTransition(async () => {
      try {
        await toggleProductActiveAction(product.id, nextState);
        router.refresh();
        showToast(nextState ? `"${product.title}" ahora está activo en la tienda.` : `"${product.title}" fue pausado (oculto del catálogo).`, "info");
      } catch (err: unknown) {
        showToast(err instanceof Error ? err.message : "Error al actualizar estado.", "error");
      }
    });
  };

  // Quick Action: Toggle Supplier Availability
  const handleToggleSupplierAvailability = (product: Product) => {
    const nextState = !product.supplierAvailable;
    startTransition(async () => {
      try {
        await toggleProductSupplierAvailabilityAction(product.id, nextState);
        router.refresh();
        showToast(nextState ? `Mayorista habilitado: disponible para clientes.` : `Disponibilidad de mayorista pausada (sin stock temporal).`, "info");
      } catch (err: unknown) {
        showToast(err instanceof Error ? err.message : "Error al cambiar disponibilidad.", "error");
      }
    });
  };

  // Quick Action: Live Single Product Supplier Stock Verification
  const handleVerifySupplierStock = (product: Product) => {
    setVerifyingId(product.id);
    startTransition(async () => {
      try {
        const result = await checkSingleProductSupplierStockAction(product.id);
        router.refresh();

        setVerificationFeedback((prev) => ({
          ...prev,
          [product.id]: { message: result.message, ok: result.available },
        }));
        showToast(result.message, result.available ? "success" : "info");
      } catch (err: unknown) {
        const msg = err instanceof Error ? err.message : "Error al conectar al mayorista";
        setVerificationFeedback((prev) => ({
          ...prev,
          [product.id]: { message: msg, ok: false },
        }));
        showToast(msg, "error");
      } finally {
        setVerifyingId(null);
      }
    });
  };

  // Batch Supplier Sync Trigger
  const handleTriggerBatchSync = () => {
    setIsBatchSyncRunning(true);
    startTransition(async () => {
      try {
        const report = await triggerBatchSupplierSyncAction(35);
        setBatchSyncReport({
          total: report.total,
          checked: report.checked,
          inStock: report.inStock,
          outOfStock: report.outOfStock,
          errors: report.errors,
          timestamp: new Date().toLocaleTimeString(),
        });
        router.refresh();
        showToast(
          `Sincronización completada: ${report.inStock} disponibles, ${report.outOfStock} sin stock pausados automáticamente.`,
          "success"
        );
      } catch (err: unknown) {
        showToast(err instanceof Error ? err.message : "Error en sincronización por lote.", "error");
      } finally {
        setIsBatchSyncRunning(false);
      }
    });
  };

  // Bulk Status Actions
  const handleBulkAction = (action: "activate" | "pause" | "supplier_available" | "supplier_pause") => {
    if (selectedIds.length === 0) return;
    startTransition(async () => {
      try {
        await bulkUpdateProductStatusAction(selectedIds, action);
        router.refresh();
        showToast(`Operación masiva aplicada a ${selectedIds.length} productos.`, "success");
        setSelectedIds([]);
      } catch (err: unknown) {
        showToast(err instanceof Error ? err.message : "Error en acción masiva.", "error");
      }
    });
  };

  // Bulk Price Adjustment Execution
  const handleExecuteBulkPrice = () => {
    if (selectedIds.length === 0) return;
    startTransition(async () => {
      try {
        await bulkAdjustPricesAction(selectedIds, bulkPriceType, bulkPriceAmount);
        router.refresh();
        showToast(`Precios actualizados para ${selectedIds.length} productos.`, "success");
        setIsBulkPriceModalOpen(false);
        setSelectedIds([]);
      } catch (err: unknown) {
        showToast(err instanceof Error ? err.message : "Error al ajustar precios.", "error");
      }
    });
  };

  // Quick Price Save
  const handleSaveQuickPrice = () => {
    if (!quickPriceProduct) return;
    startTransition(async () => {
      try {
        await quickUpdateProductPriceAction(quickPriceProduct.id, quickRetailPrice, quickWholesalePrice);
        router.refresh();
        showToast(`Precio actualizado para "${quickPriceProduct.title}".`, "success");
        setQuickPriceProduct(null);
      } catch (err: unknown) {
        showToast(err instanceof Error ? err.message : "Error al guardar precio.", "error");
      }
    });
  };

  // Copy SKU to clipboard helper
  const handleCopySku = (sku: string) => {
    navigator.clipboard.writeText(sku);
    setCopiedSku(sku);
    setTimeout(() => setCopiedSku(null), 2000);
  };

  // Copy supplier link helper
  const handleCopySupplierLink = (url: string) => {
    navigator.clipboard.writeText(url);
    setCopiedSupplierLink(url);
    showToast("✓ Enlace de proveedor copiado al portapapeles", "info");
    setTimeout(() => setCopiedSupplierLink(null), 2500);
  };

  // Delete product helper
  const handleDeleteProduct = (productId: string, title: string) => {
    if (confirm(`¿Estás seguro de eliminar permanentemente "${title}"?`)) {
      startTransition(async () => {
        try {
          await deleteProductAction(productId);
          router.refresh();
          showToast(`Producto "${title}" eliminado.`, "info");
        } catch (err: unknown) {
          showToast(err instanceof Error ? err.message : "Error al eliminar producto.", "error");
        }
      });
    }
  };

  return (
    <div className="space-y-6">
      {/* Toast Notification */}
      {toastMessage && (
        <div
          role="status"
          className={`fixed bottom-6 right-6 z-50 flex items-center gap-3 rounded-2xl px-5 py-3.5 shadow-2xl border transition-all animate-in fade-in slide-in-from-bottom-5 text-sm font-semibold ${
            toastMessage.type === "success"
              ? "bg-emerald-950 text-emerald-100 border-emerald-800"
              : toastMessage.type === "error"
              ? "bg-red-950 text-red-100 border-red-800"
              : "bg-zinc-900 text-zinc-100 border-zinc-700"
          }`}
        >
          {toastMessage.type === "success" && <CheckCircle2 className="h-5 w-5 text-emerald-400 shrink-0" />}
          {toastMessage.type === "error" && <AlertTriangle className="h-5 w-5 text-red-400 shrink-0" />}
          {toastMessage.type === "info" && <RefreshCw className="h-5 w-5 text-sky-400 shrink-0" />}
          <span>{toastMessage.text}</span>
        </div>
      )}

      {/* Top KPI Cards Bar */}
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4 lg:grid-cols-6">
        <div className="rounded-2xl border border-zinc-200 bg-white p-4 shadow-xs">
          <div className="flex items-center justify-between text-zinc-500 mb-1">
            <span className="text-xs font-semibold">Total Catálogo</span>
            <Boxes className="h-4 w-4 text-zinc-400" />
          </div>
          <p className="text-2xl font-black text-zinc-900">{stats.total.toLocaleString("es-AR")}</p>
          <span className="text-[11px] text-zinc-400 font-medium">Publicaciones cargadas</span>
        </div>

        <div className="rounded-2xl border border-emerald-200/60 bg-emerald-50/40 p-4 shadow-xs">
          <div className="flex items-center justify-between text-emerald-800 mb-1">
            <span className="text-xs font-semibold">En Línea (Activos)</span>
            <Eye className="h-4 w-4 text-emerald-600" />
          </div>
          <p className="text-2xl font-black text-emerald-900">{stats.active.toLocaleString("es-AR")}</p>
          <span className="text-[11px] text-emerald-700 font-semibold">{stats.activeRate}% del catálogo</span>
        </div>

        <div className="rounded-2xl border border-amber-200/60 bg-amber-50/40 p-4 shadow-xs">
          <div className="flex items-center justify-between text-amber-800 mb-1">
            <span className="text-xs font-semibold">Pausados / Ocultos</span>
            <EyeOff className="h-4 w-4 text-amber-600" />
          </div>
          <p className="text-2xl font-black text-amber-900">{stats.paused.toLocaleString("es-AR")}</p>
          <span className="text-[11px] text-amber-700 font-medium">Fuera de la tienda</span>
        </div>

        <div className="rounded-2xl border border-sky-200/60 bg-sky-50/40 p-4 shadow-xs">
          <div className="flex items-center justify-between text-sky-800 mb-1">
            <span className="text-xs font-semibold">Modo Proveedor</span>
            <Truck className="h-4 w-4 text-sky-600" />
          </div>
          <p className="text-2xl font-black text-sky-900">{stats.supplier.toLocaleString("es-AR")}</p>
          <span className="text-[11px] text-sky-700 font-medium">Despacho Misiones</span>
        </div>

        <div className="rounded-2xl border border-indigo-200/60 bg-indigo-50/40 p-4 shadow-xs">
          <div className="flex items-center justify-between text-indigo-800 mb-1">
            <span className="text-xs font-semibold">En Stock Mayorista</span>
            <CheckCircle2 className="h-4 w-4 text-indigo-600" />
          </div>
          <p className="text-2xl font-black text-indigo-900">{stats.supplierAvailable.toLocaleString("es-AR")}</p>
          <span className="text-[11px] text-indigo-700 font-semibold">Listos para vender</span>
        </div>

        <div className="rounded-2xl border border-red-200/60 bg-red-50/40 p-4 shadow-xs">
          <div className="flex items-center justify-between text-red-800 mb-1">
            <span className="text-xs font-semibold">Pausados Mayorista</span>
            <XCircle className="h-4 w-4 text-red-600" />
          </div>
          <p className="text-2xl font-black text-red-900">{stats.supplierPaused.toLocaleString("es-AR")}</p>
          <span className="text-[11px] text-red-700 font-medium">Sin stock en proveedor</span>
        </div>
      </div>

      {/* Supplier Batch Sync Banner / Automation Controls */}
      <div className="flex flex-col lg:flex-row items-stretch lg:items-center justify-between gap-4 rounded-2xl border border-sky-200 bg-gradient-to-r from-sky-50 via-white to-emerald-50 p-4 shadow-xs">
        <div className="flex items-start sm:items-center gap-3.5">
          <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-sky-600 text-white shadow-xs">
            <RefreshCw className={`h-5 w-5 ${isBatchSyncRunning ? "animate-spin" : ""}`} />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h3 className="text-sm font-bold text-zinc-900">Control & Sincronización Automática con Mayorista</h3>
              <span className="rounded-full bg-emerald-100 px-2 py-0.5 text-[10px] font-bold text-emerald-800">
                Programado diariamente, 06:00 UTC
              </span>
            </div>
            <p className="text-xs text-zinc-600 mt-0.5">
              La sincronización consulta la web del proveedor (Total Tools / Wadfow / Atacado USA). Cuando confirma que un
              producto se agotó, pausa su disponibilidad para prevenir ventas sin stock.
            </p>
            {batchSyncReport && (
              <p className="text-xs text-sky-800 font-semibold mt-1">
                Último reporte ({batchSyncReport.timestamp}): {batchSyncReport.checked} revisados · {batchSyncReport.inStock} con
                stock · {batchSyncReport.outOfStock} sin stock pausados · {batchSyncReport.errors} sin respuesta.
              </p>
            )}
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-2.5 shrink-0">
          <button
            type="button"
            disabled={isBatchSyncRunning || isPending}
            onClick={handleTriggerBatchSync}
            className="inline-flex h-11 items-center justify-center gap-2 rounded-xl bg-sky-600 px-4 text-xs font-bold text-white shadow-xs hover:bg-sky-700 active:scale-95 disabled:opacity-50 transition-all cursor-pointer"
          >
            <RefreshCw className={`h-4 w-4 ${isBatchSyncRunning ? "animate-spin" : ""}`} />
            {isBatchSyncRunning ? "Verificando en vivo..." : "Sincronizar Lote Ahora"}
          </button>

          <button
            type="button"
            onClick={() => setShowStockAudit(!showStockAudit)}
            className={`inline-flex h-11 items-center justify-center gap-2 rounded-xl px-4 text-xs font-semibold border transition-all cursor-pointer shadow-xs ${
              showStockAudit ? "bg-zinc-200 border-zinc-300 text-zinc-900" : "bg-white border-zinc-200 text-zinc-700 hover:bg-zinc-50"
            }`}
          >
            <TrendingUp className="h-4 w-4 text-zinc-500" />
            {showStockAudit ? "Ocultar Auditoría" : "Auditoría de Stock"}
          </button>

          {onOpenCreateProduct && (
            <button
              type="button"
              onClick={onOpenCreateProduct}
              className="inline-flex h-11 items-center justify-center gap-2 rounded-xl bg-emerald-600 px-4 text-xs font-bold text-white shadow-xs hover:bg-emerald-700 active:scale-95 transition-all cursor-pointer"
            >
              + Nuevo Producto
            </button>
          )}
        </div>
      </div>

      {/* Stock Audit Table (Expandable) */}
      {showStockAudit && (
        <div className="border border-zinc-200 rounded-2xl bg-white shadow-xs p-5 animate-in fade-in slide-in-from-top-4 duration-200">
          <div className="flex items-center justify-between border-b border-zinc-200 pb-3 mb-4">
            <h3 className="text-sm font-bold text-zinc-900 uppercase tracking-wider flex items-center gap-2">
              <TrendingUp className="h-4 w-4 text-emerald-600" /> Registro de Movimientos y Auditoría de Stock
            </h3>
            <span className="text-xs text-zinc-500 font-medium">Últimos {stockLogs.length} eventos registrados</span>
          </div>
          <div className="overflow-x-auto max-h-[300px] rounded-xl border border-zinc-200 scrollbar-thin">
            <table className="w-full text-left text-xs">
              <thead className="bg-zinc-50 border-b border-zinc-200 text-zinc-500 sticky top-0 z-10">
                <tr>
                  <th className="px-4 py-3 font-semibold">Fecha / Hora</th>
                  <th className="px-4 py-3 font-semibold">Producto</th>
                  <th className="px-4 py-3 font-semibold text-center">Modificación</th>
                  <th className="px-4 py-3 font-semibold text-center">Transición</th>
                  <th className="px-4 py-3 font-semibold text-center">Motivo</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-zinc-100">
                {stockLogs.length > 0 ? (
                  stockLogs.map((log) => {
                    const isPositive = log.changeAmount > 0;
                    return (
                      <tr key={log.id} className="hover:bg-zinc-50/50 transition-colors">
                        <td className="px-4 py-3 text-zinc-500 font-medium whitespace-nowrap">{formatDate(log.createdAt)}</td>
                        <td className="px-4 py-3 font-bold text-zinc-800">{log.productTitle}</td>
                        <td className="px-4 py-3 text-center whitespace-nowrap font-extrabold text-sm">
                          <span className={isPositive ? "text-emerald-600" : "text-red-600"}>
                            {isPositive ? `+${log.changeAmount}` : log.changeAmount}
                          </span>
                        </td>
                        <td className="px-4 py-3 text-center text-zinc-500 font-medium whitespace-nowrap">
                          {log.previousStock} → {log.newStock}
                        </td>
                        <td className="px-4 py-3 text-center whitespace-nowrap">
                          <span className="inline-flex items-center rounded-full px-2.5 py-0.5 text-[10px] font-bold border bg-zinc-100 text-zinc-700 border-zinc-200">
                            {log.reason}
                          </span>
                        </td>
                      </tr>
                    );
                  })
                ) : (
                  <tr>
                    <td colSpan={5} className="px-4 py-8 text-center text-zinc-400 italic">
                      No hay registros de auditoría de stock registrados aún.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Filter and Control Toolbar */}
      <div className="space-y-3 rounded-2xl border border-zinc-200 bg-white p-4 shadow-xs">
        <div className="flex flex-col gap-3">
          {/* Live Search */}
          <div className="relative w-full max-w-lg">
            <Search className="absolute left-3.5 top-3.5 h-4 w-4 text-zinc-400" />
            <input
              type="text"
              placeholder="Buscar por SKU, título, marca, modelo o etiqueta..."
              value={search}
              onChange={(e) => {
                setSearch(e.target.value);
                setPage(1);
              }}
              className="w-full h-11 pl-10 pr-4 rounded-xl border border-zinc-300 outline-none focus:border-emerald-600 focus:ring-2 focus:ring-emerald-500/20 bg-white text-sm transition-all"
            />
            {search && (
              <button
                type="button"
                onClick={() => setSearch("")}
                className="absolute right-3 top-3 text-xs text-zinc-400 hover:text-zinc-600"
              >
                Limpiar
              </button>
            )}
          </div>

          {/* Quick Filters */}
          <div className="flex flex-wrap items-center gap-2.5 text-xs">
            {/* Status in Shop Filter */}
            <div className="flex items-center rounded-xl border border-zinc-200 p-1 bg-zinc-50/70">
              <button
                type="button"
                onClick={() => {
                  setStatusFilter("all");
                  setPage(1);
                }}
                className={`rounded-lg px-3 py-1.5 font-bold transition-all ${
                  statusFilter === "all" ? "bg-white text-zinc-900 shadow-xs" : "text-zinc-500 hover:text-zinc-800"
                }`}
              >
                Todos ({products.length})
              </button>
              <button
                type="button"
                onClick={() => {
                  setStatusFilter("active");
                  setPage(1);
                }}
                className={`rounded-lg px-3 py-1.5 font-bold transition-all ${
                  statusFilter === "active" ? "bg-emerald-600 text-white shadow-xs" : "text-zinc-500 hover:text-zinc-800"
                }`}
              >
                Activos ({stats.active})
              </button>
              <button
                type="button"
                onClick={() => {
                  setStatusFilter("paused");
                  setPage(1);
                }}
                className={`rounded-lg px-3 py-1.5 font-bold transition-all ${
                  statusFilter === "paused" ? "bg-amber-600 text-white shadow-xs" : "text-zinc-500 hover:text-zinc-800"
                }`}
              >
                Pausados ({stats.paused})
              </button>
            </div>

            {/* Availability Filter Dropdown */}
            <select
              value={availabilityFilter}
              onChange={(e) => {
                setAvailabilityFilter(
                  e.target.value as "all" | "in_stock" | "out_of_stock" | "supplier_available" | "supplier_paused" | "own_stock"
                );
                setPage(1);
              }}
              className="h-10 rounded-xl border border-zinc-300 px-3 outline-none focus:border-emerald-600 bg-white font-medium cursor-pointer"
            >
              <option value="all">Stock: Todas las condiciones</option>
              <option value="supplier_available">🟢 Disponible en mayorista</option>
              <option value="supplier_paused">🔴 Pausado en mayorista</option>
              <option value="in_stock">✅ Con existencias</option>
              <option value="out_of_stock">⚠️ Sin existencias / Pausados</option>
              <option value="own_stock">📦 Stock propio</option>
            </select>

            {/* Supplier Link Filter Dropdown */}
            <select
              value={supplierLinkFilter}
              onChange={(e) => {
                setSupplierLinkFilter(e.target.value as "all" | "with_link" | "without_link");
                setPage(1);
              }}
              className="h-10 rounded-xl border border-zinc-300 px-3 outline-none focus:border-emerald-600 bg-white font-bold cursor-pointer"
            >
              <option value="all">🔗 Links: Todos ({products.length})</option>
              <option value="with_link">✓ Con link proveedor ({stats.withSupplierLink})</option>
              <option value="without_link">⚠️ Sin link proveedor ({stats.withoutSupplierLink})</option>
            </select>

            {/* Fulfillment Mode Dropdown */}
            <select
              value={fulfillmentFilter}
              onChange={(e) => {
                setFulfillmentFilter(e.target.value as "all" | "supplier" | "own_stock");
                setPage(1);
              }}
              className="h-10 rounded-xl border border-zinc-300 px-3 outline-none focus:border-emerald-600 bg-white font-medium cursor-pointer"
            >
              <option value="all">Modalidad: Todas</option>
              <option value="supplier">Envío Proveedor (Misiones)</option>
              <option value="own_stock">Stock Propio</option>
            </select>

            {/* Category Dropdown */}
            <select
              value={categoryFilter}
              onChange={(e) => {
                setCategoryFilter(e.target.value);
                setPage(1);
              }}
              className="h-10 rounded-xl border border-zinc-300 px-3 outline-none focus:border-emerald-600 bg-white font-medium cursor-pointer max-w-44"
            >
              <option value="">Todas las categorías</option>
              {mainCategories.map((category) => (
                <optgroup key={category.id} label={category.name}>
                  <option value={category.id}>Todo {category.name}</option>
                  {categories
                    .filter((item) => item.parentId === category.id)
                    .map((subcategory) => (
                      <option key={subcategory.id} value={subcategory.id}>
                        {subcategory.name}
                      </option>
                    ))}
                </optgroup>
              ))}
            </select>

            {/* Brand Dropdown */}
            {distinctBrands.length > 0 && (
              <select
                value={brandFilter}
                onChange={(e) => {
                  setBrandFilter(e.target.value);
                  setPage(1);
                }}
                className="h-10 rounded-xl border border-zinc-300 px-3 outline-none focus:border-emerald-600 bg-white font-medium cursor-pointer max-w-36"
              >
                <option value="">Todas las marcas</option>
                {distinctBrands.map((b) => (
                  <option key={b} value={b}>
                    {b}
                  </option>
                ))}
              </select>
            )}

            {/* Sort Dropdown */}
            <select
              value={sortBy}
              onChange={(e) =>
                setSortBy(e.target.value as "name" | "price_asc" | "price_desc" | "status" | "recent")
              }
              className="h-10 rounded-xl border border-zinc-300 px-3 outline-none focus:border-emerald-600 bg-white font-medium cursor-pointer"
            >
              <option value="recent">Ordenar: Catálogo original</option>
              <option value="name">Nombre: A → Z</option>
              <option value="price_asc">Precio: Menor a Mayor</option>
              <option value="price_desc">Precio: Mayor a Menor</option>
              <option value="status">Estado: Activos primero</option>
            </select>
          </div>
        </div>

        {/* Selected Items Bulk Actions Bar */}
        {selectedIds.length > 0 && (
          <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl bg-zinc-900 px-4 py-3 text-white animate-in fade-in slide-in-from-top-2 duration-150">
            <div className="flex items-center gap-2 text-xs font-bold">
              <span className="flex h-6 w-6 items-center justify-center rounded-full bg-emerald-500 text-zinc-950 font-black">
                {selectedIds.length}
              </span>
              <span>seleccionados</span>
              <button
                type="button"
                onClick={() => setSelectedIds([])}
                className="text-zinc-400 hover:text-white underline ml-2 cursor-pointer"
              >
                Deseleccionar
              </button>
            </div>

            <div className="flex flex-wrap items-center gap-2 text-xs font-semibold">
              <button
                type="button"
                onClick={() => handleBulkAction("activate")}
                className="rounded-lg bg-emerald-600 hover:bg-emerald-500 px-3 py-1.5 transition-colors cursor-pointer"
              >
                Activar en tienda
              </button>
              <button
                type="button"
                onClick={() => handleBulkAction("pause")}
                className="rounded-lg bg-amber-600 hover:bg-amber-500 px-3 py-1.5 transition-colors cursor-pointer"
              >
                Pausar en tienda
              </button>
              <button
                type="button"
                onClick={() => handleBulkAction("supplier_available")}
                className="rounded-lg bg-sky-600 hover:bg-sky-500 px-3 py-1.5 transition-colors cursor-pointer"
              >
                Habilitar mayorista
              </button>
              <button
                type="button"
                onClick={() => handleBulkAction("supplier_pause")}
                className="rounded-lg bg-red-600 hover:bg-red-500 px-3 py-1.5 transition-colors cursor-pointer"
              >
                Pausar mayorista
              </button>
              <button
                type="button"
                onClick={() => setIsBulkPriceModalOpen(true)}
                className="rounded-lg bg-zinc-800 hover:bg-zinc-700 border border-zinc-700 px-3 py-1.5 transition-colors cursor-pointer flex items-center gap-1.5"
              >
                <Percent className="h-3.5 w-3.5 text-emerald-400" />
                Ajustar precios
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Main Products Table */}
      <div className="overflow-hidden rounded-2xl border border-zinc-200 bg-white shadow-xs">
        <div className="overflow-x-auto">
          <table className="admin-card-table w-full min-w-[1000px] text-left text-sm">
            <thead className="bg-zinc-50 border-b border-zinc-200 text-zinc-500 text-xs font-semibold uppercase tracking-wider">
              <tr>
                <th className="px-4 py-3.5 w-12 text-center">
                  <input
                    type="checkbox"
                    checked={isAllPageSelected}
                    onChange={toggleSelectAllPage}
                    className="h-4 w-4 rounded border-zinc-300 text-emerald-600 focus:ring-emerald-500 cursor-pointer"
                  />
                </th>
                <th className="px-4 py-3.5">Producto & Identidad</th>
                <th className="px-4 py-3.5">Categoría</th>
                <th className="px-4 py-3.5">Precios & Margen</th>
                <th className="px-4 py-3.5">Abastecimiento & Mayorista</th>
                <th className="px-4 py-3.5 text-center">Estado Tienda</th>
                <th className="px-4 py-3.5 text-center w-28">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-zinc-100">
              {paginatedProducts.length === 0 ? (
                <tr>
                  <td colSpan={7} className="px-6 py-16 text-center text-zinc-500">
                    <div className="flex flex-col items-center justify-center max-w-sm mx-auto">
                      <div className="h-12 w-12 rounded-2xl bg-zinc-100 flex items-center justify-center text-zinc-400 mb-3">
                        <Package className="h-6 w-6" />
                      </div>
                      <p className="font-bold text-zinc-800 text-base">No se encontraron productos</p>
                      <p className="text-xs text-zinc-400 mt-1">
                        {search || categoryFilter || brandFilter || statusFilter !== "all" || availabilityFilter !== "all"
                          ? "Probá ajustando o limpiando los filtros de búsqueda aplicados."
                          : "Comenzá creando tu primer producto con el botón '+ Nuevo Producto'."}
                      </p>
                    </div>
                  </td>
                </tr>
              ) : (
                paginatedProducts.map((product) => {
                  const isSelected = selectedIds.includes(product.id);
                  const isLiveChecking = verifyingId === product.id;
                  const feedback = verificationFeedback[product.id];
                  const prodCategory = categories.find((c) => c.id === product.categoryId);
                  let categoryDisplay = product.categoryName;
                  if (prodCategory && prodCategory.parentId) {
                    const parent = categories.find((c) => c.id === prodCategory.parentId);
                    if (parent) categoryDisplay = `${parent.name} > ${prodCategory.name}`;
                  }

                  const isActive = product.active !== false;

                  return (
                    <tr
                      key={product.id}
                      className={`hover:bg-zinc-50/60 transition-colors ${
                        isSelected ? "bg-emerald-50/30" : ""
                      } ${!isActive ? "opacity-75 bg-zinc-50/40" : ""}`}
                    >
                      {/* Select Checkbox */}
                      <td data-label="Seleccionar" className="px-4 py-3.5 text-center">
                        <input
                          type="checkbox"
                          checked={isSelected}
                          onChange={() => toggleSelectProduct(product.id)}
                          className="h-4 w-4 rounded border-zinc-300 text-emerald-600 focus:ring-emerald-500 cursor-pointer"
                        />
                      </td>

                      {/* Product identity */}
                      <td data-label="Producto" className="px-4 py-3.5">
                        <div className="flex items-start gap-3">
                          {product.imageUrl ? (
                            <img
                              src={product.imageUrl}
                              alt={product.title}
                              className="h-12 w-12 shrink-0 rounded-xl object-cover border border-zinc-200 shadow-2xs"
                              loading="lazy"
                            />
                          ) : (
                            <div className="h-12 w-12 shrink-0 rounded-xl bg-zinc-100 flex items-center justify-center text-zinc-400 border border-dashed border-zinc-300">
                              <Package className="h-5 w-5" />
                            </div>
                          )}

                          <div className="min-w-0 flex-1">
                            <button
                              type="button"
                              onClick={() => setEditingProduct(product)}
                              className="text-left font-bold text-zinc-900 hover:text-emerald-700 block line-clamp-1 text-sm cursor-pointer transition-colors"
                              title={product.title}
                            >
                              {product.title}
                            </button>

                            <div className="flex flex-wrap items-center gap-1.5 mt-1">
                              {product.sku && (
                                <button
                                  type="button"
                                  onClick={() => handleCopySku(product.sku!)}
                                  className="inline-flex items-center gap-1 rounded bg-zinc-100 hover:bg-zinc-200 px-1.5 py-0.5 text-[10px] font-mono font-bold text-zinc-700 transition-colors cursor-pointer"
                                  title="Click para copiar SKU"
                                >
                                  {copiedSku === product.sku ? <Check className="h-2.5 w-2.5 text-emerald-600" /> : <Copy className="h-2.5 w-2.5 text-zinc-400" />}
                                  SKU: {product.sku}
                                </button>
                              )}

                              {product.brand && (
                                <span className="inline-flex items-center rounded bg-zinc-100 px-1.5 py-0.5 text-[10px] font-semibold text-zinc-700">
                                  {product.brand}
                                </span>
                              )}

                              {product.sourceUrl && (
                                <a
                                  href={product.sourceUrl}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  className="inline-flex items-center gap-1 rounded bg-sky-50 hover:bg-sky-100 px-1.5 py-0.5 text-[10px] font-bold text-sky-700 border border-sky-200/50 transition-colors"
                                  title="Ver página oficial en la web del mayorista"
                                >
                                  <Globe className="h-2.5 w-2.5" /> Mayorista
                                  <ExternalLink className="h-2.5 w-2.5" />
                                </a>
                              )}

                              {product.featured && (
                                <span className="inline-flex items-center rounded bg-amber-50 px-1.5 py-0.5 text-[10px] font-bold text-amber-800 border border-amber-200/50">
                                  ★ Destacado
                                </span>
                              )}
                            </div>
                          </div>
                        </div>
                      </td>

                      {/* Category */}
                      <td data-label="Categoría" className="px-4 py-3.5 text-zinc-600 text-xs">
                        <span className="inline-flex items-center gap-1 font-medium bg-zinc-100 text-zinc-700 px-2 py-0.5 rounded-lg border border-zinc-200/70 max-w-44 truncate">
                          <Layers className="h-3 w-3 text-zinc-400 shrink-0" />
                          <span className="truncate">{categoryDisplay}</span>
                        </span>
                      </td>

                      {/* Prices & Quick Edit */}
                      <td data-label="Precios" className="px-4 py-3.5">
                        <div className="flex items-center gap-2">
                          <div>
                            <div className="font-black text-zinc-950 text-sm">
                              {formatCurrency(product.retailPrice)}
                            </div>
                            <div className="text-[11px] text-zinc-400 font-medium">
                              Mayorista: {formatCurrency(product.wholesalePrice)} (mín {product.wholesaleMinQuantity})
                            </div>
                          </div>

                          <button
                            type="button"
                            onClick={() => {
                              setQuickPriceProduct(product);
                              setQuickRetailPrice(product.retailPrice);
                              setQuickWholesalePrice(product.wholesalePrice);
                            }}
                            className="inline-flex h-7 w-7 items-center justify-center rounded-lg border border-zinc-200 text-zinc-500 hover:text-zinc-900 hover:bg-zinc-100 transition-colors cursor-pointer"
                            title="Modificar precio rápido"
                          >
                            <DollarSign className="h-3.5 w-3.5" />
                          </button>
                        </div>
                      </td>

                      {/* Fulfillment & Supplier Link / Availability */}
                      <td data-label="Abastecimiento" className="px-4 py-3.5">
                        <div className="space-y-2">
                          {/* Supplier Direct Link & Actions */}
                          {product.sourceUrl ? (
                            <div className="space-y-1">
                              <div className="flex items-center gap-1.5 flex-wrap">
                                <a
                                  href={product.sourceUrl}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  className="inline-flex items-center gap-1 rounded-lg bg-sky-50 text-sky-800 hover:bg-sky-100 border border-sky-300 px-2 py-0.5 text-xs font-bold transition-all shadow-2xs"
                                  title="Abrir página oficial del mayorista en nueva pestaña"
                                >
                                  <Globe className="h-3 w-3 text-sky-600" /> Abrir proveedor <ExternalLink className="h-3 w-3" />
                                </a>

                                <button
                                  type="button"
                                  onClick={() => handleCopySupplierLink(product.sourceUrl!)}
                                  className="inline-flex h-6 w-6 items-center justify-center rounded-lg border border-zinc-200 text-zinc-500 hover:text-zinc-900 bg-white shadow-2xs transition-colors cursor-pointer"
                                  title="Copiar enlace del mayorista"
                                >
                                  {copiedSupplierLink === product.sourceUrl ? (
                                    <Check className="h-3 w-3 text-emerald-600" />
                                  ) : (
                                    <Copy className="h-3 w-3" />
                                  )}
                                </button>

                                <button
                                  type="button"
                                  onClick={() => setQuickSupplierProduct(product)}
                                  className="inline-flex h-6 w-6 items-center justify-center rounded-lg border border-zinc-200 text-zinc-500 hover:text-sky-700 bg-white shadow-2xs transition-colors cursor-pointer"
                                  title="Modificar enlace, costo o disponibilidad"
                                >
                                  <Edit className="h-3 w-3" />
                                </button>
                              </div>

                              {/* Live Price & Gross Margin */}
                              {product.supplierLivePrice ? (
                                <div className="flex items-center gap-1.5 text-[10px]">
                                  <span className="font-semibold text-zinc-500">
                                    Costo: {formatCurrency(product.supplierLivePrice)}
                                  </span>
                                  {product.retailPrice > product.supplierLivePrice && (
                                    <span className="rounded bg-emerald-50 px-1.5 py-0.5 text-[10px] font-bold text-emerald-800 border border-emerald-200">
                                      +{Math.round(((product.retailPrice - product.supplierLivePrice) / product.retailPrice) * 100)}% mrg
                                    </span>
                                  )}
                                </div>
                              ) : null}
                            </div>
                          ) : (
                            <div className="space-y-1">
                              <button
                                type="button"
                                onClick={() => setQuickSupplierProduct(product)}
                                className="inline-flex items-center gap-1 rounded-xl border border-dashed border-sky-400 bg-sky-50/70 hover:bg-sky-100 text-sky-800 px-2.5 py-1 text-xs font-bold transition-all cursor-pointer shadow-2xs"
                                title="Vincular el enlace directo de la web del mayorista"
                              >
                                <Plus className="h-3.5 w-3.5" /> Vincular proveedor
                              </button>
                              <span className="text-[10px] text-amber-700 font-semibold block">
                                ⚠️ Falta enlace de mayorista
                              </span>
                            </div>
                          )}

                          {/* Mode Badge & Availability Switch */}
                          <div className="flex items-center gap-1.5 pt-0.5">
                            {product.fulfillmentMode === "supplier" ? (
                              <div className="flex items-center gap-1.5">
                                <button
                                  type="button"
                                  onClick={() => handleToggleSupplierAvailability(product)}
                                  className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-bold border transition-all cursor-pointer ${
                                    product.supplierAvailable
                                      ? "bg-emerald-50 text-emerald-800 border-emerald-300 hover:bg-emerald-100"
                                      : "bg-red-50 text-red-800 border-red-300 hover:bg-red-100"
                                  }`}
                                  title="Click para alternar disponibilidad en el mayorista"
                                >
                                  {product.supplierAvailable ? (
                                    <>
                                      <CheckCircle2 className="h-3 w-3 text-emerald-600" />
                                      <span>Disponible</span>
                                    </>
                                  ) : (
                                    <>
                                      <XCircle className="h-3 w-3 text-red-600" />
                                      <span>Pausado</span>
                                    </>
                                  )}
                                </button>

                                <button
                                  type="button"
                                  disabled={isLiveChecking}
                                  onClick={() => handleVerifySupplierStock(product)}
                                  className="inline-flex h-5 items-center gap-1 rounded bg-zinc-100 hover:bg-zinc-200 px-1.5 text-[9px] font-bold text-zinc-700 transition-colors cursor-pointer disabled:opacity-50"
                                  title="Verificar stock en vivo en la web del mayorista"
                                >
                                  <RefreshCw className={`h-2.5 w-2.5 ${isLiveChecking ? "animate-spin text-sky-600" : ""}`} />
                                  {isLiveChecking ? "..." : "Sync"}
                                </button>
                              </div>
                            ) : (
                              <span className="inline-flex items-center gap-1 rounded-full bg-indigo-50 px-2 py-0.5 text-[10px] font-bold text-indigo-800 border border-indigo-200">
                                <Boxes className="h-3 w-3 text-indigo-600" />
                                Stock Propio ({product.stockVerifiedAt ? `${product.stock} un.` : "Sin verificar"})
                              </span>
                            )}
                          </div>

                          {feedback && (
                            <p className={`text-[10px] font-bold ${feedback.ok ? "text-emerald-700" : "text-amber-800"}`}>
                              {feedback.message}
                            </p>
                          )}
                        </div>
                      </td>

                      {/* Status in Retail Shop (Active / Paused switch) */}
                      <td data-label="Estado en tienda" className="px-4 py-3.5 text-center">
                        <button
                          type="button"
                          onClick={() => handleToggleActive(product)}
                          className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1 text-xs font-bold border transition-all cursor-pointer ${
                            isActive
                              ? "bg-emerald-50 text-emerald-800 border-emerald-300 hover:bg-emerald-100"
                              : "bg-zinc-100 text-zinc-500 border-zinc-300 hover:bg-zinc-200"
                          }`}
                          title={isActive ? "Click para pausar publicación en la tienda" : "Click para activar en la tienda"}
                        >
                          <span className={`h-2 w-2 rounded-full ${isActive ? "bg-emerald-500 animate-pulse" : "bg-zinc-400"}`} />
                          {isActive ? "Activo" : "Pausado"}
                        </button>
                      </td>

                      {/* Row Actions */}
                      <td data-label="Acciones" className="px-4 py-3.5 text-center">
                        <div className="flex items-center justify-center gap-1.5">
                          <button
                            type="button"
                            onClick={() => setEditingProduct(product)}
                            className="inline-flex h-8 w-8 items-center justify-center rounded-xl border border-zinc-200 text-zinc-600 hover:bg-zinc-100 hover:text-zinc-950 transition-colors cursor-pointer bg-white shadow-2xs"
                            title="Editar ficha completa"
                          >
                            <Edit className="h-4 w-4" />
                          </button>

                          <a
                            href={`/producto/${product.slug}`}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex h-8 w-8 items-center justify-center rounded-xl border border-zinc-200 text-zinc-600 hover:bg-zinc-100 hover:text-zinc-950 transition-colors cursor-pointer bg-white shadow-2xs"
                            title="Ver en la tienda pública"
                          >
                            <ExternalLink className="h-4 w-4" />
                          </a>

                          <button
                            type="button"
                            onClick={() => handleDeleteProduct(product.id, product.title)}
                            className="inline-flex h-8 w-8 items-center justify-center rounded-xl border border-red-100 text-red-600 hover:bg-red-50 hover:text-red-700 transition-colors cursor-pointer bg-white shadow-2xs"
                            title="Eliminar producto"
                          >
                            <Trash2 className="h-4 w-4" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination & Counter Footer */}
        <div className="flex flex-wrap items-center justify-between gap-4 border-t border-zinc-200 bg-white p-4 text-xs text-zinc-600 sm:px-6">
          <div className="flex items-center gap-3">
            <span>
              Mostrando <strong>{paginatedProducts.length}</strong> de <strong>{filteredProducts.length}</strong> productos
              (Página {currentPage} de {totalPages})
            </span>

            <div className="flex items-center gap-1.5 ml-2">
              <span className="text-zinc-400">Por página:</span>
              <select
                value={pageSize}
                onChange={(e) => {
                  setPageSize(Number(e.target.value));
                  setPage(1);
                }}
                className="rounded-lg border border-zinc-300 px-2 py-1 bg-white font-semibold cursor-pointer"
              >
                <option value={10}>10</option>
                <option value={15}>15</option>
                <option value={25}>25</option>
