            />
          </div>

          <div className="grid gap-3 sm:grid-cols-2">
            <div>
              <label className="block text-xs font-bold text-zinc-700">
                Costo en Proveedor (ARS)
              </label>
              <input
                type="number"
                min="0"
                step="1"
                placeholder="Ej. 18500"
                value={supplierLivePrice}
                onChange={(e) => setSupplierLivePrice(e.target.value ? Number(e.target.value) : "")}
                className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-sm font-bold text-zinc-950 focus:border-sky-500"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-zinc-700">Modalidad de entrega</label>
              <select
                value={fulfillmentMode}
                onChange={(e) => setFulfillmentMode(e.target.value as "supplier" | "own_stock")}
                className="mt-1 w-full rounded-xl border border-zinc-300 bg-white p-2.5 text-xs font-semibold text-zinc-800"
              >
                <option value="supplier">Envío directo de proveedor</option>
                <option value="own_stock">Stock físico propio</option>
              </select>
            </div>
          </div>

          <label className="flex items-center gap-2.5 rounded-xl border border-zinc-200 bg-zinc-50 p-3 text-xs font-medium text-zinc-800 cursor-pointer">
            <input
              type="checkbox"
              checked={supplierAvailable}
              onChange={(e) => setSupplierAvailable(e.target.checked)}
              className="rounded border-zinc-300 text-emerald-600 focus:ring-emerald-500"
            />
            <span>
              <strong>Proveedor disponible:</strong> El artículo está en stock en el mayorista y listo para despachar.
            </span>
          </label>

          <div className="flex items-center justify-end gap-2 pt-2">
            <button
              type="button"
              onClick={onClose}
              className="rounded-xl border border-zinc-300 px-4 py-2 text-xs font-semibold text-zinc-700 hover:bg-zinc-100"
            >
              Cancelar
            </button>
            <button
              type="submit"
              disabled={isPending}
              className="rounded-xl bg-zinc-950 px-5 py-2 text-xs font-bold text-white shadow-xs hover:bg-zinc-800 disabled:opacity-50"
            >
              {isPending ? "Guardando…" : "Guardar Proveedor"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

// -----------------------------------------------------------------------------
// SUB-MODAL 3: Full Financial Control Modal
// -----------------------------------------------------------------------------
function FinancialControlModal({
  product,
  costRecord,
  onClose,
  onSuccess,
}: {
  product: Product;
  costRecord?: ProductCost;
  onClose: () => void;
  onSuccess: (msg: string) => void;
}) {
  const [isPending, startTransition] = useTransition();
  const [errorMessage, setErrorMessage] = useState("");

  const [values, setValues] = useState({
    purchase: Number(costRecord?.origin_cost || 0),
    exchange: Number(costRecord?.exchange_rate || 1),
    freight: Number(costRecord?.freight_per_unit || 0),
    other: Number(costRecord?.other_landed_cost || 0),
    variable: Number(costRecord?.variable_cost || 0),
    fee: Number(costRecord?.payment_fee_percent || 0),
    minimum: Number(costRecord?.minimum_contribution || 0),
    sale: product.retailPrice,
  });

  const [currency, setCurrency] = useState(costRecord?.currency || "ARS");
  const [sourceUrl, setSourceUrl] = useState(costRecord?.supplier_url || product.sourceUrl || "");
  const [mode, setMode] = useState<"supplier" | "own_stock">(product.fulfillmentMode || "supplier");
  const [available, setAvailable] = useState(product.supplierAvailable ?? true);
  const [stock, setStock] = useState<number | "">(product.stockVerifiedAt ? product.stock : "");
  const [stockConfirmed, setStockConfirmed] = useState(false);
  const [expensesConfirmed, setExpensesConfirmed] = useState(costRecord?.expenses_confirmed ?? false);

  // Dynamic profit calculation
  const dynamicProfit = useMemo(() => {
    return calculateProductProfit(values.sale, {
      product_id: product.id,
      origin_cost: values.purchase,
      currency,
      exchange_rate: values.exchange,
      freight_per_unit: values.freight,
      other_landed_cost: values.other,
      variable_cost: values.variable,
      payment_fee_percent: values.fee,
      minimum_contribution: values.minimum,
      expenses_confirmed: expensesConfirmed,
    });
  }, [values, currency, expensesConfirmed, product.id]);

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setErrorMessage("");

    const formData = new FormData(e.currentTarget);
    formData.set("product_id", product.id);
    formData.set("currency", currency);
    formData.set("source_url", sourceUrl);
    formData.set("mode", mode);
    if (available) formData.set("available", "on");
    if (expensesConfirmed) formData.set("expenses_confirmed", "on");
    if (stockConfirmed && stock !== "") {
      formData.set("stock", String(stock));
      formData.set("stock_confirmed", "on");
    }

    startTransition(async () => {
      try {
        const msg = await saveFinancialControl(formData);
        onSuccess(msg);
      } catch (err: unknown) {
        setErrorMessage(err instanceof Error ? err.message : "Error al guardar costos.");
      }
    });
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center overflow-y-auto bg-black/60 p-2 sm:p-4 backdrop-blur-xs animate-in fade-in">
      <div className="my-auto w-full max-w-3xl min-h-0 flex flex-col rounded-2xl bg-white shadow-2xl border border-zinc-200 overflow-hidden max-h-[calc(100dvh-1rem)] sm:max-h-[92dvh]">
        <div className="flex items-center justify-between p-4 sm:p-5 border-b border-zinc-100 bg-white shrink-0">
          <div className="min-w-0 flex-1 pr-2">
            <h2 className="text-base sm:text-lg font-bold text-zinc-950 truncate">Ajuste Integral de Costos & Ganancia</h2>
            <p className="text-xs text-zinc-500 mt-0.5 truncate">{product.title}</p>
          </div>
          <button onClick={onClose} className="rounded-lg p-1.5 text-zinc-400 hover:bg-zinc-100 shrink-0 cursor-pointer">
            <X className="h-5 w-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="min-h-0 flex-1 flex flex-col overflow-hidden">
          <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain p-4 sm:p-6 space-y-6">
          {/* Section 1: Purchase and Currency */}
          <div>
            <div className="flex items-center justify-between border-b border-zinc-100 pb-1 mb-3">
              <span className="text-xs font-bold uppercase tracking-wider text-zinc-700">
                1. Proveedor & Moneda de Compra
              </span>
              <div className="flex items-center gap-2">
                <span className="text-xs text-zinc-500">Moneda:</span>
                <select
                  value={currency}
                  onChange={(e) => {
                    setCurrency(e.target.value);
                    if (e.target.value === "ARS") setValues((v) => ({ ...v, exchange: 1 }));
                  }}
                  className="rounded-lg border border-zinc-300 bg-white px-2 py-1 text-xs font-bold text-zinc-800"
                >
                  <option value="ARS">ARS ($)</option>
                  <option value="USD">USD (U$D)</option>
                  <option value="PYG">PYG (₲)</option>
                </select>
              </div>
            </div>

            <div className="grid gap-3 sm:grid-cols-2">
              <div className="sm:col-span-2">
                <div className="flex items-center justify-between">
                  <label className="text-xs font-semibold text-zinc-700">
                    URL directa del proveedor
                  </label>
                  {sourceUrl && (
                    <a
                      href={sourceUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="inline-flex items-center gap-1 text-xs text-sky-600 hover:underline"
                    >
                      Probar enlace <ExternalLink className="h-3 w-3" />
                    </a>
                  )}
                </div>
                <input
                  type="url"
                  placeholder="https://..."
                  value={sourceUrl}
                  onChange={(e) => setSourceUrl(e.target.value)}
                  className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-xs text-zinc-800"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-zinc-700">
                  Costo de compra en origen ({currency})
                </label>
                <input
                  required
                  name="purchase"
                  type="number"
                  min="0"
                  step="0.01"
                  value={values.purchase}
                  onChange={(e) => setValues({ ...values, purchase: Number(e.target.value) })}
                  className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-sm font-bold text-zinc-900 focus:border-emerald-500"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-zinc-700">
                  Conversión a ARS {currency === "ARS" && "(Fijo en 1)"}
                </label>
                <input
                  required
                  name="exchange"
                  type="number"
                  min="0.001"
                  step="0.01"
                  disabled={currency === "ARS"}
                  value={currency === "ARS" ? 1 : values.exchange}
                  onChange={(e) => setValues({ ...values, exchange: Number(e.target.value) })}
                  className="mt-1 w-full rounded-xl border border-zinc-300 bg-zinc-50 p-2.5 text-sm font-semibold disabled:opacity-60"
                />
              </div>
            </div>
          </div>

          {/* Section 2: Freight and Landed Costs */}
          <div>
            <span className="block text-xs font-bold uppercase tracking-wider text-zinc-700 border-b border-zinc-100 pb-1 mb-3">
              2. Logística, Flete & Gastos de Internación
            </span>
            <div className="grid gap-3 sm:grid-cols-2">
              <div>
                <label className="block text-xs font-semibold text-zinc-700">
                  Transporte / Flete unitario en ARS
                </label>
                <input
                  required
                  name="freight"
                  type="number"
                  min="0"
                  step="0.01"
                  value={values.freight}
                  onChange={(e) => setValues({ ...values, freight: Number(e.target.value) })}
                  className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-sm font-medium"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-zinc-700">
                  Otros costos de ingreso en ARS
                </label>
                <input
                  required
                  name="other"
                  type="number"
                  min="0"
                  step="0.01"
                  value={values.other}
                  onChange={(e) => setValues({ ...values, other: Number(e.target.value) })}
                  className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-sm font-medium"
                />
              </div>
            </div>
          </div>

          {/* Section 3: Fees & Commercial Sales */}
          <div>
            <span className="block text-xs font-bold uppercase tracking-wider text-zinc-700 border-b border-zinc-100 pb-1 mb-3">
              3. Gastos de Venta, Pasarela & Precio
            </span>
            <div className="grid gap-3 sm:grid-cols-2">
              <div>
                <label className="block text-xs font-semibold text-zinc-700">
                  Gastos de venta / embalaje (ARS)
                </label>
                <input
                  required
                  name="variable"
                  type="number"
                  min="0"
                  step="0.01"
                  value={values.variable}
                  onChange={(e) => setValues({ ...values, variable: Number(e.target.value) })}
                  className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-sm font-medium"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-zinc-700">
                  Comisión pasarela / cobro (%)
                </label>
                <input
                  required
                  name="fee"
                  type="number"
                  min="0"
                  max="99"
                  step="0.1"
                  value={values.fee}
                  onChange={(e) => setValues({ ...values, fee: Number(e.target.value) })}
                  className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-sm font-medium"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-zinc-700">
                  Contribución mínima en ARS
                </label>
                <input
                  required
                  name="minimum"
                  type="number"
                  min="0"
                  step="0.01"
                  value={values.minimum}
                  onChange={(e) => setValues({ ...values, minimum: Number(e.target.value) })}
                  className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-sm font-medium"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-emerald-900">
                  Precio de venta al público (PVP ARS)
                </label>
                <input
                  required
                  name="sale"
                  type="number"
                  min="1"
                  step="1"
                  value={values.sale}
                  onChange={(e) => setValues({ ...values, sale: Number(e.target.value) })}
                  className="mt-1 w-full rounded-xl border border-emerald-400 bg-emerald-50/50 p-2.5 text-sm font-black text-emerald-950 focus:border-emerald-500"
                />
              </div>
            </div>
          </div>

          {/* Section 4: Live Dynamic Profit Breakdown Card */}
          {dynamicProfit && (
            <div className="rounded-2xl border border-zinc-200 bg-zinc-900 p-5 text-white space-y-3">
              <span className="text-xs font-bold uppercase tracking-wider text-zinc-400">
                Simulación en Tiempo Real
              </span>
              <div className="grid grid-cols-2 gap-3 sm:grid-cols-4 text-xs">
                <div>
                  <span className="text-zinc-400">Costo Puesto:</span>
                  <p className="text-sm font-bold text-zinc-100">{money(dynamicProfit.landed)}</p>
                </div>
                <div>
                  <span className="text-zinc-400">Comisión cobro:</span>
                  <p className="text-sm font-bold text-zinc-100">{money(dynamicProfit.fees)}</p>
                </div>
                <div>
                  <span className="text-zinc-400">Ganancia neta:</span>
                  <p
                    className={`text-sm font-bold ${
                      dynamicProfit.contribution > 0 ? "text-emerald-400" : "text-rose-400"
                    }`}
                  >
                    {money(dynamicProfit.contribution)}
                  </p>
                </div>
                <div>
                  <span className="text-zinc-400">Margen sobre venta:</span>
                  <p
                    className={`text-base font-black ${
                      dynamicProfit.margin > 25
                        ? "text-emerald-400"
                        : dynamicProfit.margin > 0
                        ? "text-amber-400"
                        : "text-rose-400"
                    }`}
                  >
                    {dynamicProfit.margin > 0
                      ? `+${dynamicProfit.margin.toFixed(1)}%`
                      : `${dynamicProfit.margin.toFixed(1)}%`}
                  </p>
                </div>
              </div>
            </div>
          )}

          {/* Section 5: Delivery Mode & Physical Stock Verification */}
          <div className="rounded-2xl border border-zinc-200 bg-zinc-50 p-4 space-y-3">
            <span className="text-xs font-bold uppercase tracking-wider text-zinc-800">
              4. Modalidad de Entrega & Stock Físico
            </span>

            <div className="grid gap-3 sm:grid-cols-2">
              <div>
                <label className="block text-xs font-semibold text-zinc-700">Modalidad</label>
                <select
                  value={mode}
                  onChange={(e) => setMode(e.target.value as "supplier" | "own_stock")}
                  className="mt-1 w-full rounded-xl border border-zinc-300 bg-white p-2.5 text-xs font-semibold"
                >
                  <option value="supplier">Envío directo del proveedor</option>
                  <option value="own_stock">Stock físico propio</option>
                </select>
              </div>

              {mode === "supplier" ? (
                <div className="flex items-center pt-5">
                  <label className="flex items-center gap-2 text-xs font-semibold text-zinc-800 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={available}
                      onChange={(e) => setAvailable(e.target.checked)}
                      className="rounded border-zinc-300 text-emerald-600 focus:ring-emerald-500"
                    />
                    Proveedor disponible para pedidos
                  </label>
                </div>
              ) : (
                <div>
                  <label className="block text-xs font-semibold text-zinc-700">
                    Unidades físicas verificadas
                  </label>
                  <input
                    type="number"
                    min="0"
                    max="100000"
                    step="1"
                    placeholder="Dejar vacío para no modificar"
                    value={stock}
                    onChange={(e) => setStock(e.target.value === "" ? "" : Number(e.target.value))}
                    className="mt-1 w-full rounded-xl border border-zinc-300 bg-white p-2.5 text-xs font-bold"
                  />
                  {stock !== "" && (
                    <label className="mt-2 flex items-center gap-2 text-[11px] font-semibold text-zinc-700 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={stockConfirmed}
                        onChange={(e) => setStockConfirmed(e.target.checked)}
                        className="rounded border-zinc-300 text-sky-600"
                      />
                      Conté estas unidades físicamente
                    </label>
                  )}
                </div>
              )}
            </div>
          </div>

          {/* Confirmation Checkbox */}
          <label className="flex items-center gap-2 text-xs font-medium text-zinc-700 cursor-pointer">
            <input
              type="checkbox"
              checked={expensesConfirmed}
              onChange={(e) => setExpensesConfirmed(e.target.checked)}
              className="rounded border-zinc-300 text-emerald-600 focus:ring-emerald-500"
            />
            Confirmé los importes de flete, comisión y costos de internación.
          </label>

          {errorMessage && (
            <div className="rounded-xl border border-rose-300 bg-rose-50 p-3 text-xs font-semibold text-rose-800">
              {errorMessage}
            </div>
          )}

          </div>

          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-end gap-2.5 p-4 sm:p-5 border-t border-zinc-200 bg-zinc-50 shrink-0">
            <button
              type="button"
              onClick={onClose}
              className="w-full sm:w-auto rounded-xl border border-zinc-300 px-5 py-2.5 text-xs font-semibold text-zinc-700 hover:bg-zinc-200 transition-colors text-center cursor-pointer"
            >
              Cerrar
            </button>
            <button
              type="submit"
              disabled={isPending}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 rounded-xl bg-zinc-950 px-6 py-2.5 text-xs font-bold text-white shadow-md hover:bg-zinc-800 disabled:opacity-50 transition-colors text-center cursor-pointer"
            >
              {isPending ? "Guardando…" : "Guardar Costos y Precio"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import { useState, useMemo, useTransition } from "react";
import { calculateResale, type ResaleInput } from "@/lib/resale-pricing";
import { formatCurrency as money } from "@/lib/format";
import { saveProductCostAction } from "@/app/admin/costos/actions";
import type { Product } from "@/lib/types";
import type { ProductCost } from "@/lib/product-profit";
import {
  Calculator,
  Search,
  ExternalLink,
  CheckCircle2,
  AlertTriangle,
  TrendingUp,
  Percent,
  DollarSign,
  Package,
  Layers,
  ArrowRight,
  ShieldAlert,
} from "lucide-react";

interface RealCostsProps {
  products: Product[];
  costs?: ProductCost[];
  onSaved?: () => void;
}

export function RealCosts({ products, costs = [], onSaved }: RealCostsProps) {
  const [productSearch, setProductSearch] = useState("");
  const [selectedProductId, setSelectedProductId] = useState("");
  const [currency, setCurrency] = useState("ARS");
  const [supplierUrl, setSupplierUrl] = useState("");
  const [mlUrl, setMlUrl] = useState("");
  const [applyRetailPrice, setApplyRetailPrice] = useState(false);
  const [confirmed, setConfirmed] = useState(false);

  const [input, setInput] = useState<ResaleInput>({
    purchase: 25000,
    exchange: 1,
    freight: 4500,
    other: 0,
    variable: 1200,
    feePercent: 8,
    minimum: 5000,
    ml: 55000,
  });

  const [message, setMessage] = useState<{ text: string; type: "success" | "error" } | null>(null);
  const [isPending, startTransition] = useTransition();

  const costsMap = useMemo(() => new Map(costs.map((c) => [c.product_id, c])), [costs]);

  // Filter products for the searchable dropdown
  const displayedProducts = useMemo(() => {
    const q = productSearch.toLowerCase().trim();
    const filtered = q
      ? products.filter(
          (p) =>
            p.title.toLowerCase().includes(q) ||
            (p.sku && p.sku.toLowerCase().includes(q)) ||
            (p.brand && p.brand.toLowerCase().includes(q))
        )
      : products;
    const selected = selectedProductId ? products.find((p) => p.id === selectedProductId) : null;
    const top = filtered.slice(0, 60);
    if (selected && !top.some((p) => p.id === selectedProductId)) {
      return [selected, ...top];
    }
    return top;
  }, [products, productSearch, selectedProductId]);

  const selectedProduct = useMemo(
    () => products.find((p) => p.id === selectedProductId),
    [products, selectedProductId]
  );

  // When a product is picked, auto-populate inputs
  const handleSelectProduct = (productId: string) => {
    setSelectedProductId(productId);
    setMessage(null);
    if (!productId) return;

    const prod = products.find((p) => p.id === productId);
    if (!prod) return;

    const recordedCost = costsMap.get(productId);

    if (recordedCost) {
      setInput({
        purchase: Number(recordedCost.origin_cost || prod.supplierLivePrice || prod.retailPrice / 2),
        exchange: Number(recordedCost.exchange_rate || 1),
        freight: Number(recordedCost.freight_per_unit || 0),
        other: Number(recordedCost.other_landed_cost || 0),
        variable: Number(recordedCost.variable_cost || 0),
        feePercent: Number(recordedCost.payment_fee_percent || 0),
        minimum: Number(recordedCost.minimum_contribution || 0),
        ml: Number(recordedCost.ml_price || 0),
      });
      setCurrency(recordedCost.currency || "ARS");
      setSupplierUrl(recordedCost.supplier_url || prod.sourceUrl || "");
      setMlUrl(recordedCost.ml_url || "");
    } else {
      setInput((prev) => ({
        ...prev,
        purchase: Number(prod.supplierLivePrice || Math.round(prod.retailPrice * 0.5)),
        exchange: 1,
      }));
      setSupplierUrl(prod.sourceUrl || "");
      setMlUrl("");
    }
  };

  // Safe calculate resale
  const result = useMemo(() => {
    try {
      if (input.purchase <= 0 || input.exchange <= 0) return null;
      return calculateResale(input);
    } catch {
      return null;
    }
  }, [input]);

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!selectedProductId) {
      setMessage({ text: "Seleccioná un producto para guardar.", type: "error" });
      return;
    }
    if (!confirmed) {
      setMessage({ text: "Tenés que confirmar que revisaste las fuentes.", type: "error" });
      return;
    }

    const formData = new FormData(e.currentTarget);
    if (applyRetailPrice && result?.suggested) {
      formData.set("apply_retail_price", String(result.suggested));
    }

    startTransition(async () => {
      try {
        const res = await saveProductCostAction(formData);
        setMessage({ text: res, type: "success" });
        if (onSaved) onSaved();
      } catch (err: unknown) {
        setMessage({
          text: err instanceof Error ? err.message : "Error al guardar costos.",
          type: "error",
        });
      }
    });
  };

  return (
    <div className="rounded-2xl border border-zinc-200/90 bg-white p-6 shadow-sm sm:p-8">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between pb-6 border-b border-zinc-100 gap-4">
        <div>
          <div className="inline-flex items-center gap-1.5 rounded-full bg-amber-50 px-3 py-1 text-xs font-semibold text-amber-800 border border-amber-200">
            <Calculator className="h-3.5 w-3.5 text-amber-600" />
            Estrategia de Mercado Libre
          </div>
          <h2 className="mt-2 text-2xl font-bold tracking-tight text-zinc-950">
            Simulador de Referencia & Fijación de Precios
          </h2>
          <p className="mt-1 text-sm text-zinc-500">
            Comprobá el piso de costos reales, compará contra Mercado Libre y calculá el precio sugerido de venta (5% a 10% de ahorro para el cliente).
          </p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="mt-6 space-y-6">
        {/* Product selector card */}
        <div className="rounded-2xl border border-zinc-200 bg-zinc-50/70 p-5">
          <label className="block text-xs font-bold uppercase tracking-wider text-zinc-700">
            1. Seleccionar Producto del Catálogo
          </label>
          <div className="mt-2 grid gap-3 sm:grid-cols-2">
            <div>
              <div className="relative">
                <Search className="absolute left-3 top-3 h-4 w-4 text-zinc-400" />
                <input
                  type="text"
                  placeholder="Filtrar por nombre, SKU o marca..."
                  value={productSearch}
                  onChange={(e) => setProductSearch(e.target.value)}
                  className="w-full rounded-xl border border-zinc-300 bg-white py-2.5 pl-9 pr-3 text-sm focus:border-amber-500 focus:outline-hidden focus:ring-2 focus:ring-amber-500/20"
                />
              </div>
            </div>
            <div>
              <select
                required
                name="product_id"
                value={selectedProductId}
                onChange={(e) => handleSelectProduct(e.target.value)}
                className="w-full rounded-xl border border-zinc-300 bg-white py-2.5 px-3 text-sm font-medium text-zinc-800 focus:border-amber-500 focus:outline-hidden focus:ring-2 focus:ring-amber-500/20"
              >
                <option value="">-- Elegí un producto ({displayedProducts.length} listados) --</option>
                {displayedProducts.map((p) => (
                  <option key={p.id} value={p.id}>
                    {p.title} {p.sku ? `[${p.sku}]` : ""} — PVP Actual: ${p.retailPrice.toLocaleString("es-AR")}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {selectedProduct && (
            <div className="mt-3 flex flex-wrap items-center gap-3 rounded-xl border border-zinc-200 bg-white p-3 text-xs text-zinc-600">
              <span className="font-semibold text-zinc-900">{selectedProduct.title}</span>
              {selectedProduct.sku && <span className="rounded bg-zinc-100 px-2 py-0.5 font-mono">SKU: {selectedProduct.sku}</span>}
              <span className="rounded bg-sky-50 px-2 py-0.5 text-sky-800 font-medium">PVP Actual: ${selectedProduct.retailPrice.toLocaleString("es-AR")}</span>
              {selectedProduct.supplierLivePrice && (
                <span className="rounded bg-emerald-50 px-2 py-0.5 text-emerald-800 font-medium">
                  Costo Proveedor: ${selectedProduct.supplierLivePrice.toLocaleString("es-AR")}
                </span>
              )}
            </div>
          )}
        </div>

        {/* Inputs & Parameters */}
        <div className="grid gap-6 lg:grid-cols-12">
          {/* Left: Input parameters (7 cols) */}
          <div className="space-y-4 lg:col-span-7">
            <div className="flex items-center justify-between">
              <h3 className="text-sm font-bold text-zinc-900 uppercase tracking-wider">
                2. Estructura de Costos y Referencia
              </h3>
              <div className="flex items-center gap-2">
                <span className="text-xs text-zinc-500 font-medium">Moneda:</span>
                <select
                  name="currency"
                  value={currency}
                  onChange={(e) => {
                    setCurrency(e.target.value);
                    if (e.target.value === "ARS") {
                      setInput((prev) => ({ ...prev, exchange: 1 }));
                    }
                  }}
                  className="rounded-lg border border-zinc-300 bg-white px-2 py-1 text-xs font-semibold text-zinc-700"
                >
                  <option value="ARS">ARS ($)</option>
                  <option value="USD">USD (U$D)</option>
                  <option value="PYG">PYG (₲)</option>
                </select>
              </div>
            </div>

            <div className="grid gap-3 sm:grid-cols-2">
              <div>
                <label className="block text-xs font-semibold text-zinc-700">
                  Costo de compra unitario ({currency})
                </label>
                <input
                  name="purchase"
                  required
                  type="number"
                  min="1"
                  step="0.01"
                  value={input.purchase || ""}
                  onChange={(e) => setInput({ ...input, purchase: Number(e.target.value) })}
                  className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-sm font-semibold focus:border-amber-500 focus:ring-1 focus:ring-amber-500"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-zinc-700">
                  Tipo de cambio a ARS {currency === "ARS" && "(Fijo en 1)"}
                </label>
                <input
                  name="exchange"
                  required
                  type="number"
                  min="0.001"
                  step="0.01"
                  disabled={currency === "ARS"}
                  value={currency === "ARS" ? 1 : input.exchange || ""}
                  onChange={(e) => setInput({ ...input, exchange: Number(e.target.value) })}
                  className="mt-1 w-full rounded-xl border border-zinc-300 bg-zinc-50 p-2.5 text-sm font-semibold disabled:opacity-60"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-zinc-700">
                  Flete / Transporte por unidad (ARS)
                </label>
                <input
                  name="freight"
                  required
                  type="number"
                  min="0"
                  step="0.01"
                  value={input.freight}
                  onChange={(e) => setInput({ ...input, freight: Number(e.target.value) })}
                  className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-sm font-medium"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-zinc-700">
                  Otros costos de internación (ARS)
                </label>
                <input
                  name="other"
                  required
                  type="number"
                  min="0"
                  step="0.01"
                  value={input.other}
                  onChange={(e) => setInput({ ...input, other: Number(e.target.value) })}
                  className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-sm font-medium"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-zinc-700">
                  Gastos de venta / embalaje (ARS)
                </label>
                <input
                  name="variable"
                  required
                  type="number"
                  min="0"
                  step="0.01"
                  value={input.variable}
                  onChange={(e) => setInput({ ...input, variable: Number(e.target.value) })}
                  className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-sm font-medium"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-zinc-700">
                  Comisión de pasarela / cobro (%)
                </label>
                <input
                  name="feePercent"
                  required
                  type="number"
                  min="0"
                  max="99"
                  step="0.1"
                  value={input.feePercent}
                  onChange={(e) => setInput({ ...input, feePercent: Number(e.target.value) })}
                  className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-sm font-medium"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-zinc-700">
                  Contribución mínima deseada (ARS)
                </label>
                <input
                  name="minimum"
                  required
                  type="number"
                  min="0"
                  step="0.01"
                  value={input.minimum}
                  onChange={(e) => setInput({ ...input, minimum: Number(e.target.value) })}
                  className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-sm font-medium"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-amber-900">
                  Precio referencia en Mercado Libre (ARS)
                </label>
                <input
                  name="ml"
                  required
                  type="number"
                  min="0"
                  step="1"
                  value={input.ml || ""}
                  onChange={(e) => setInput({ ...input, ml: Number(e.target.value) })}
                  className="mt-1 w-full rounded-xl border border-amber-300 bg-amber-50/50 p-2.5 text-sm font-bold text-amber-950 focus:border-amber-500 focus:ring-1 focus:ring-amber-500"
                />
              </div>
            </div>

            {/* Links */}
            <div className="space-y-3 pt-2">
              <div>
                <div className="flex items-center justify-between">
                  <label className="text-xs font-semibold text-zinc-700">
                    URL de la publicación del Proveedor
                  </label>
                  {supplierUrl && (
                    <a
                      href={supplierUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="inline-flex items-center gap-1 text-xs text-sky-600 hover:underline"
                    >
                      Probar enlace <ExternalLink className="h-3 w-3" />
                    </a>
                  )}
                </div>
                <input
                  type="url"
                  name="supplier_url"
                  required
                  value={supplierUrl}
                  onChange={(e) => setSupplierUrl(e.target.value)}
                  placeholder="https://..."
                  className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-xs text-zinc-800 focus:border-amber-500"
                />
              </div>

              <div>
                <div className="flex items-center justify-between">
                  <label className="text-xs font-semibold text-zinc-700">
                    URL de publicación en Mercado Libre (mismo modelo/presentación)
                  </label>
                  {mlUrl && (
                    <a
                      href={mlUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="inline-flex items-center gap-1 text-xs text-amber-600 hover:underline"
                    >
                      Ver en ML <ExternalLink className="h-3 w-3" />
                    </a>
                  )}
                </div>
                <input
                  type="url"
                  name="ml_url"
                  value={mlUrl}
                  onChange={(e) => setMlUrl(e.target.value)}
                  placeholder="https://articulo.mercadolibre.com.ar/MLA-..."
                  className="mt-1 w-full rounded-xl border border-zinc-300 p-2.5 text-xs text-zinc-800 focus:border-amber-500"
                />
              </div>
            </div>
          </div>

          {/* Right: Real-time simulation results (5 cols) */}
          <div className="space-y-4 lg:col-span-5">
            <h3 className="text-sm font-bold text-zinc-900 uppercase tracking-wider">
              3. Resultado en Tiempo Real
            </h3>

            {result ? (
              <div className="space-y-3 rounded-2xl border border-zinc-200 bg-zinc-900 p-6 text-white shadow-lg">
                <div className="flex items-center justify-between border-b border-zinc-800 pb-3">
                  <span className="text-xs font-medium text-zinc-400">Costo Puesto (Landed)</span>
                  <span className="text-base font-bold text-zinc-100">{money(result.landed)}</span>
                </div>

                <div className="flex items-center justify-between border-b border-zinc-800 pb-3">
                  <span className="text-xs font-medium text-zinc-400">Piso mínimo rentable</span>
                  <span className="text-base font-bold text-amber-400">{money(result.floor)}</span>
                </div>

                {input.ml > 0 && (
                  <div className="rounded-xl bg-zinc-800/80 p-3.5 space-y-2">
                    <div className="flex items-center justify-between text-xs">
                      <span className="text-zinc-400">Referencia Mercado Libre</span>
                      <span className="font-semibold text-zinc-200">{money(input.ml)}</span>
                    </div>
                    <div className="flex items-center justify-between text-xs">
                      <span className="text-zinc-400">Rango sugerido (-5% a -10%)</span>
                      <span className="font-mono text-zinc-300">
                        {money(result.low)} – {money(result.high)}
                      </span>
                    </div>
                  </div>
                )}

                <div className="rounded-xl bg-emerald-950/80 border border-emerald-700/60 p-4">
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-bold uppercase tracking-wider text-emerald-300">
                      Precio de Venta Sugerido
                    </span>
                    {result.suggested !== null ? (
                      <span className="text-xl font-extrabold text-emerald-300">
                        {money(result.suggested)}
                      </span>
                    ) : (
                      <span className="text-xs font-semibold text-amber-400">
                        No viable debajo de ML
                      </span>
                    )}
                  </div>
                  {result.suggested !== null ? (
                    <div className="mt-3 flex items-center justify-between border-t border-emerald-800/80 pt-2 text-xs">
                      <span className="text-emerald-200/80">Contribución neta estimada:</span>
                      <strong className="text-emerald-300">
                        {money(result.contribution ?? 0)} (
                        {((result.contribution! / result.suggested) * 100).toFixed(1)}% margen)
                      </strong>
                    </div>
                  ) : (
                    <p className="mt-2 text-xs text-amber-300/80 leading-relaxed">
                      El costo piso ({money(result.floor)}) supera el techo del 95% de Mercado Libre ({money(result.high)}). Para vender este producto rentablemente se debe reducir flete, compra o no ofrecer descuento frente a ML.
                    </p>
                  )}
                </div>

                {result.suggested !== null && selectedProduct && (
                  <label className="flex items-start gap-2.5 rounded-xl border border-sky-800/50 bg-sky-950/40 p-3 text-xs text-sky-200 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={applyRetailPrice}
                      onChange={(e) => setApplyRetailPrice(e.target.checked)}
                      className="mt-0.5 rounded border-sky-700 text-sky-500 focus:ring-sky-400"
                    />
                    <span>
                      <strong>Aplicar este precio a la tienda pública:</strong> Actualizar el precio minorista del producto a <strong>{money(result.suggested)}</strong> al guardar.
                    </span>
                  </label>
                )}
              </div>
            ) : (
              <div className="flex h-56 flex-col items-center justify-center rounded-2xl border border-dashed border-zinc-300 bg-zinc-50 p-6 text-center text-sm text-zinc-500">
                <AlertTriangle className="h-8 w-8 text-amber-500 mb-2" />
                <p className="font-semibold text-zinc-700">Completá los costos de compra</p>
                <p className="text-xs text-zinc-400 mt-1">
                  Ingresá el costo unitario para calcular la viabilidad y precios recomendados.
                </p>
              </div>
            )}
          </div>
        </div>

        {/* Bottom confirmation & submit */}
        <div className="border-t border-zinc-200 pt-5 space-y-4">
          <label className="flex items-center gap-2 text-xs font-medium text-zinc-700 cursor-pointer">
            <input
              required
              type="checkbox"
              name="confirmed"
              checked={confirmed}
              onChange={(e) => setConfirmed(e.target.checked)}
              className="rounded border-zinc-300 text-amber-600 focus:ring-amber-500"
            />
            Confirmé costos del proveedor y la referencia equivalente de Mercado Libre.
          </label>

          {message && (
            <div
              className={`rounded-xl p-3.5 text-xs font-semibold ${
                message.type === "success"
                  ? "bg-emerald-50 text-emerald-800 border border-emerald-200"
                  : "bg-red-50 text-red-800 border border-red-200"
              }`}
            >
              {message.text}
            </div>
          )}

          <div className="flex flex-wrap items-center justify-between gap-3">
            <p className="text-xs text-zinc-500 max-w-xl">
              Al guardar, se registrará la estructura analítica de costos y enlaces. Si marcaste la casilla superior, el precio de venta en la web se actualizará al valor sugerido.
            </p>
            <button
              type="submit"
              disabled={isPending || !selectedProductId || !confirmed || !result}
              className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl bg-zinc-950 px-6 text-sm font-bold text-white shadow-md hover:bg-zinc-800 disabled:opacity-50 transition-all cursor-pointer"
            >
              {isPending ? (
                "Guardando costos…"
              ) : (
                <>
                  <CheckCircle2 className="h-4 w-4 text-emerald-400" />
                  Guardar Costos Verificados
                </>
              )}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
}

"use client";

import { useState, useMemo, useTransition } from "react";
import {
  Calculator,
  TrendingUp,
  DollarSign,
  Truck,
  Building2,
  Copy,
  Check,
  MessageCircle,
  ExternalLink,
  Sparkles,
  ArrowRight,
  ShieldCheck,
  Boxes,
  Percent,
  Download,
  CheckCircle2,
  AlertCircle,
  Package,
} from "lucide-react";
import { formatCurrency } from "@/lib/format";
import { siteConfig } from "@/lib/site";
import { updateProductPricesAction } from "@/app/admin/actions";
import type { Category, Product } from "@/lib/types";

interface SupplierResaleSystemProps {
  products: Product[];
  categories: Category[];
  customSuppliers?: Array<{ id: string; name: string; categoryType?: string; url?: string }>;
}

export function SupplierResaleSystem({
  products,
  categories,
  customSuppliers = [],
}: SupplierResaleSystemProps) {
  const [isPending, startTransition] = useTransition();

  // Mode: existing catalog product vs custom simulation
  const [mode, setMode] = useState<"catalog" | "custom">("catalog");
  const [selectedProductId, setSelectedProductId] = useState<string>(products[0]?.id || "");

  // Custom product fields
  const [customTitle, setCustomTitle] = useState("Amoladora Angular 850W Total Tools");
  const [customCategory, setCustomCategory] = useState("Herramientas Eléctricas");
  const [customSupplier, setCustomSupplier] = useState("Total Tools Paraguay");

  // Currency & cost configuration
  const [currency, setCurrency] = useState<"USD" | "PYG" | "ARS">("USD");
  const [costInput, setCostInput] = useState<number>(28);
  const [exchangeUsdArs, setExchangeUsdArs] = useState<number>(1350);
  const [exchangePygArs, setExchangePygArs] = useState<number>(5.6); // 5.6 PYG = 1 ARS (approx 7.560 PYG/USD)
  
  // Logistics & Margins
  const [logisticsPercent, setLogisticsPercent] = useState<number>(12); // Flete + Aduana/Frontera
  const [myaMarkupPercent, setMyaMarkupPercent] = useState<number>(20); // Ganancia MYA sobre costo puesto
  const [retailMultiplier, setRetailMultiplier] = useState<number>(2.0); // Ecuación base: 2.0x costo
  const [mercadoLibreMarkup, setMercadoLibreMarkup] = useState<number>(8); // Referencia ML sobre PVP (5-10% sobre PVP)

  // Reseller Pack volume quantity
  const [packQuantity, setPackQuantity] = useState<number>(12);

  // Status & copy feedback
  const [copiedQuote, setCopiedQuote] = useState(false);
  const [actionSuccess, setActionSuccess] = useState<string | null>(null);

  // Selected product object
  const selectedProduct = useMemo(() => {
    return products.find((p) => p.id === selectedProductId) || null;
  }, [products, selectedProductId]);

  // If a catalog product is chosen, infer default cost in USD based on retail price / 2
  const activeTitle = mode === "catalog" ? selectedProduct?.title || "Producto" : customTitle;
  const activeCategory = mode === "catalog" ? selectedProduct?.categoryName || "General" : customCategory;

  // When changing selected product, update default cost
  const handleProductSelect = (prodId: string) => {
    setSelectedProductId(prodId);
    const p = products.find((x) => x.id === prodId);
    if (p) {
      // Estimated origin USD cost: retailPrice / 2.0 / exchangeUsdArs
      const estimatedUsd = Math.round((p.retailPrice / (retailMultiplier || 2.0) / exchangeUsdArs) * 10) / 10;
      setCostInput(estimatedUsd > 0 ? estimatedUsd : 25);
    }
  };

  // 1. Financial Calculations
  const calculations = useMemo(() => {
    // A. Convert origin cost to ARS
    let costInArs = 0;
    if (currency === "USD") {
      costInArs = costInput * exchangeUsdArs;
    } else if (currency === "PYG") {
      costInArs = exchangePygArs > 0 ? costInput / exchangePygArs : 0;
    } else {
      costInArs = costInput;
    }

    // B. Landed Cost in Tandil (Costo puesto con flete y frontera)
    const freightAmount = costInArs * (logisticsPercent / 100);
    const landedCost = Math.round(costInArs + freightAmount);

    // C. MYA Wholesale B2B Price (Precio al que MYA le vende al revendedor)
    const myaWholesalePrice = Math.round(landedCost * (1 + myaMarkupPercent / 100));
    const myaProfitPerUnit = myaWholesalePrice - landedCost;
    const myaProfitMargin = myaWholesalePrice > 0 ? (myaProfitPerUnit / myaWholesalePrice) * 100 : 0;

    // D. Suggested Retail Price (PVP Recomendado al público)
    // Formula: 2.0x Landed Cost
    const suggestedRetailPrice = Math.round(landedCost * retailMultiplier);

    // E. Reseller Profit Margin (Lo que gana el cliente revendedor)
    const resellerProfitPerUnit = Math.max(0, suggestedRetailPrice - myaWholesalePrice);
    const resellerMarginPercent = suggestedRetailPrice > 0 
      ? (resellerProfitPerUnit / suggestedRetailPrice) * 100 
      : 0;
    const resellerRoiPercent = myaWholesalePrice > 0 
      ? (resellerProfitPerUnit / myaWholesalePrice) * 100 
      : 0;

    // F. Mercado Libre Benchmark
    const estimatedMlPrice = Math.round(suggestedRetailPrice * (1 + mercadoLibreMarkup / 100));
    const savingVsMl = Math.max(0, estimatedMlPrice - suggestedRetailPrice);
    const savingPercentVsMl = estimatedMlPrice > 0 ? (savingVsMl / estimatedMlPrice) * 100 : 0;

    // G. Reseller Batch Packs
    const packTiers = [
      { qty: 6, label: "Pack Inicial (6 un.)" },
      { qty: 12, label: "Caja Cerrada (12 un.)" },
      { qty: 24, label: "Lote Mayorista (24 un.)" },
      { qty: packQuantity, label: `Personalizado (${packQuantity} un.)` },
    ];

    const packCalculations = packTiers.map((tier) => {
      const totalInvestment = myaWholesalePrice * tier.qty;
      const totalRevenue = suggestedRetailPrice * tier.qty;
      const totalResellerProfit = resellerProfitPerUnit * tier.qty;
      const totalMyaProfit = myaProfitPerUnit * tier.qty;
      return {
        ...tier,
        totalInvestment,
        totalRevenue,
        totalResellerProfit,
        totalMyaProfit,
      };
    });

    return {
      costInArs: Math.round(costInArs),
      landedCost,
      freightAmount: Math.round(freightAmount),
      myaWholesalePrice,
      myaProfitPerUnit,
      myaProfitMargin,
      suggestedRetailPrice,
      resellerProfitPerUnit,
      resellerMarginPercent,
      resellerRoiPercent,
      estimatedMlPrice,
      savingVsMl,
      savingPercentVsMl,
      packCalculations,
    };
  }, [
    currency,
    costInput,
    exchangeUsdArs,
    exchangePygArs,
    logisticsPercent,
    myaMarkupPercent,
    retailMultiplier,
    mercadoLibreMarkup,
    packQuantity,
  ]);

  // 2. WhatsApp B2B Pitch Message Generator
  const whatsappPitchMessage = useMemo(() => {
    return `🔥 *COTIZACIÓN MAYORISTA B2B - MYA IMPORTACIONES* 🔥
📍 Distribución directa desde Tandil para todo el país.

📦 *Producto:* ${activeTitle}
🏷️ *Rubro:* ${activeCategory}

💰 *TU PRECIO MAYORISTA (MYA):* ${formatCurrency(calculations.myaWholesalePrice)} / unidad
⚡ *PVP Sugerido al público:* ${formatCurrency(calculations.suggestedRetailPrice)}
📈 *TU GANANCIA NETA:* ${formatCurrency(calculations.resellerProfitPerUnit)} por unidad (*${calculations.resellerMarginPercent.toFixed(0)}% de margen*)

📊 *ESCALAS POR VOLUMEN:*
• Pack x6 unidades: Inversión ${formatCurrency(calculations.myaWholesalePrice * 6)} ➔ Ganás ${formatCurrency(calculations.resellerProfitPerUnit * 6)} limpios.
• Caja cerrada x12: Inversión ${formatCurrency(calculations.myaWholesalePrice * 12)} ➔ Ganás ${formatCurrency(calculations.resellerProfitPerUnit * 12)} limpios.

🛒 *COMPARATIVA MERCADO LIBRE:*
En Mercado Libre este producto ronda los *${formatCurrency(calculations.estimatedMlPrice)}*. 
¡Vendiendo a nuestro PVP sugerido, le ganás a Mercado Libre por un *${calculations.savingPercentVsMl.toFixed(0)}% DE AHORRO* y dejás a tus clientes fascinados!

✅ Stock disponible para despacho inmediato.
🚚 Envíos a todo el país (Correo Argentino / Andreani / Transporte).
📲 Respondé este mensaje para reservar tu pedido.`;
  }, [activeTitle, activeCategory, calculations]);

  // Copy WhatsApp Pitch
  const handleCopyPitch = async () => {
    try {
      await navigator.clipboard.writeText(whatsappPitchMessage);
      setCopiedQuote(true);
      setTimeout(() => setCopiedQuote(false), 3000);
    } catch {
      // fallback
    }
  };

  // Direct WhatsApp Share Link
  const whatsappShareUrl = `https://api.whatsapp.com/send?text=${encodeURIComponent(whatsappPitchMessage)}`;

  // Apply to Catalog Action
  const handleApplyToCatalog = () => {
    if (mode === "catalog" && selectedProduct) {
      startTransition(async () => {
        try {
          const res = await updateProductPricesAction(
            selectedProduct.id,
            calculations.suggestedRetailPrice,
            calculations.myaWholesalePrice
          );
          if (res.success) {
            setActionSuccess(`¡Precios de "${selectedProduct.title}" actualizados exitosamente en la tienda!`);
            setTimeout(() => setActionSuccess(null), 4000);
          }
        } catch (err: unknown) {
          alert((err instanceof Error ? err.message : "Error inesperado") || "Error al actualizar.");
        }
      });
    } else {
      alert("Para guardar este producto en la base de datos, agregalo desde la pestaña 'Productos' o usa el Ajustador Masivo.");
    }
  };

  // Export CSV simulation
  const handleExportCsv = () => {
    const headers = [
      "Producto",
      "Categoria",
      "Moneda Origen",
      "Costo Origen",
      "Costo Puesto ARS",
      "Mayorista MYA ARS",
      "PVP Sugerido ARS",
      "Ganancia Revendedor ARS",
      "Margen Revendedor %",
      "Ref Mercado Libre ARS",
      "Ahorro vs ML %",
    ];

    const row = [
      `"${activeTitle.replace(/"/g, '""')}"`,
      `"${activeCategory}"`,
      currency,
      costInput,
      calculations.landedCost,
      calculations.myaWholesalePrice,
      calculations.suggestedRetailPrice,
      calculations.resellerProfitPerUnit,
      `${calculations.resellerMarginPercent.toFixed(1)}%`,
      calculations.estimatedMlPrice,
      `${calculations.savingPercentVsMl.toFixed(1)}%`,
    ];

    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(","), row.join(",")].join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `mya-cotizacion-b2b-${Date.now()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-200">
      {/* Top Banner */}
      <div className="rounded-2xl border border-emerald-200 bg-gradient-to-br from-emerald-900 via-zinc-900 to-zinc-950 p-6 md:p-8 text-white shadow-xl relative overflow-hidden">
        <div className="absolute right-0 top-0 translate-x-10 -translate-y-10 w-96 h-96 bg-emerald-500/10 rounded-full blur-3xl pointer-events-none" />
        <div className="relative z-10">
          <div className="inline-flex items-center gap-2 rounded-full border border-emerald-500/30 bg-emerald-500/20 px-3.5 py-1 text-xs font-bold text-emerald-300">
            <Calculator className="h-3.5 w-3.5" />
            Sistema Comercial B2B & Margen de Reventa
          </div>
          <h2 className="mt-3 text-2xl md:text-3xl font-black tracking-tight text-white">
            Calculadora de Costos de Proveedor, Precios Mayoristas & Reventa Sugerida
          </h2>
          <p className="mt-2 text-sm text-zinc-300 max-w-3xl leading-relaxed">
            Determiná con precisión matemática tu costo de compra en origen (USD / Guaraníes / ARS), fletes y aduana.
            Generá automáticamente tu precio de venta mayorista y el <strong>PVP de reventa sugerido</strong> para demostrarle a tus clientes revendedores exactamente cuánto dinero van a ganar vendiendo tus productos y por qué le ganan a Mercado Libre.
          </p>

          <div className="mt-6 flex flex-wrap gap-3">
            <button
              onClick={() => setMode("catalog")}
              className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${
                mode === "catalog"
                  ? "bg-emerald-500 text-zinc-950 shadow-lg shadow-emerald-500/20"
                  : "bg-white/10 hover:bg-white/20 text-white"
              }`}
            >
              Seleccionar Producto del Catálogo ({products.length})
            </button>
            <button
              onClick={() => setMode("custom")}
              className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${
                mode === "custom"
                  ? "bg-emerald-500 text-zinc-950 shadow-lg shadow-emerald-500/20"
                  : "bg-white/10 hover:bg-white/20 text-white"
              }`}
            >
              Simular Producto / Proveedor Personalizado
            </button>
          </div>
        </div>
      </div>

      {actionSuccess && (
        <div className="rounded-xl border border-emerald-300 bg-emerald-50 p-4 text-sm font-semibold text-emerald-900 flex items-center gap-3">
          <CheckCircle2 className="h-5 w-5 text-emerald-600 shrink-0" />
          {actionSuccess}
        </div>
      )}

      {/* Main Grid: Inputs (Left) & Results (Right) */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Left Column: Product selection & Inputs */}
        <div className="lg:col-span-6 space-y-6">
          <div className="rounded-2xl border border-zinc-200 bg-white p-6 shadow-sm space-y-5">
            <h3 className="text-base font-bold text-zinc-900 flex items-center gap-2">
              <Package className="h-5 w-5 text-emerald-600" />
              1. Identificación del Producto & Proveedor
            </h3>

            {mode === "catalog" ? (
              <div>
                <label className="block text-xs font-bold uppercase tracking-wider text-zinc-600 mb-1.5">
                  Producto de la Tienda
                </label>
                <select
                  value={selectedProductId}
                  onChange={(e) => handleProductSelect(e.target.value)}
                  className="w-full rounded-xl border border-zinc-300 bg-zinc-50 px-3.5 py-2.5 text-sm font-medium text-zinc-900 focus:border-emerald-500 focus:bg-white focus:outline-none"
                >
                  {products.map((p) => (
                    <option key={p.id} value={p.id}>
                      [{p.categoryName}] {p.title} - Actual: {formatCurrency(p.retailPrice)}
                    </option>
                  ))}
                </select>
                {selectedProduct && (
                  <div className="mt-3 p-3 bg-zinc-50 rounded-xl border border-zinc-200 text-xs text-zinc-600 flex items-center justify-between">
                    <span>Precio Minorista Actual: <strong>{formatCurrency(selectedProduct.retailPrice)}</strong></span>
