  Zap,
  Clock,
} from "lucide-react";
import { formatCurrency, formatPaymentMethod } from "@/lib/format";
import { useCommerce } from "@/components/commerce/commerce-provider";
import {
  calculateShipping,
  isProductImmediateStock,
